function pickPal(input: TemplateInput, fx: EffectKey[]): { id: string; label: string } {
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  const hit = PALS.find(([re]) => re.test(text));
  if (hit) return { id: hit[1], label: hit[2] };
  const byFx = fx.map((k) => BY_EFFECT[k]).find(Boolean);
  if (byFx) return { id: byFx[0], label: byFx[1] };
  const [, id, label] = PALS[hashStr(input.modName) % PALS.length];
  return { id, label };
}

/** DT_ItemDataTable rows; swap for the weapon you're retuning. */
function pickWeapon(text: string): string {
  if (/bow|arrow/.test(text)) return "Bow";
  if (/shotgun/.test(text)) return "PumpActionShotgun";
  if (/pistol|handgun|revolver/.test(text)) return "HandGun_Default";
  if (/spear|glaive|lance/.test(text)) return "Spear";
  if (/rocket|launcher/.test(text)) return "RocketLauncher_Default";
  return "AssaultRifle_Default1";
}

