function enumBlock() {
  return code`

    --- Reads a UEnum into { ShortName = value } so we never hard-code indices that shift between patches.
    local function enumValues(path)
        local values = {}
        local enum = StaticFindObject(path)
        if M.valid(enum) then
            enum:ForEachName(function(name, value)
                local full = name:ToString()
                values[full:match("::(.+)$") or full] = value
            end)
        end
        return values
    end

    local Element, Effect
    local function enums()
        if not Element then
            Element = enumValues("/Script/Pal.EPalElementType")
            Effect = enumValues("/Script/Pal.EPalAdditionalEffectType")
        end
        return Element, Effect
    end`;
}

/* ───────────── archetype modules ───────────── */

interface Ctx {
  input: TemplateInput;
  n: N;
  cls: string;
  snake: string;
  fx: EffectKey[];
  tint: [number, number, number];
  pal: { id: string; label: string };
  text: string;
}

interface Mode {
  /** Module file under Scripts/<snake>/ and its local name in main.lua. */
  file: string;
  local: string;
  summary: string;
  needs: string[];
  ue?: boolean;
  /** False when the module doesn't run effect snippets (overlay, audio, post-process). */
  fx?: boolean;
  defs: Def[];
  body: string;
  hooks: string;
  strings: Record<string, string>;
  spec: string;
}

const hit = (c: Ctx, target: string, source: string) => c.fx.map((k) => sub(FX[k].hit, target, source));
const pulse = (c: Ctx, target: string, source: string) => c.fx.map((k) => sub(FX[k].pulse, target, source));
const COOLDOWN = { cooldown: "Recharging · %.1fs" };

function damageHook(local: string) {
  return code`
    -- plausible: every hit funnels through the defender's UPalDamageReactionComponent; confirm the
    -- UFunction in Pal/PalDamageReactionComponent.hpp. Pre-hook, so edits to the struct reach the call.
    RegisterHook("/Script/Pal.PalDamageReactionComponent:ApplyDamageForMP", function(self, damageInfo)
        ${local}.onDamage(self:get(), damageInfo:get())
    end)`;
}

const keyBind = (key: string, call: string, ctrl = false) => code`
  RegisterKeyBind(Key[Config.${key}], ${ctrl ? "{ ModifierKey.CONTROL }, " : ""}function()
      ExecuteInGameThread(${call.endsWith("()") ? call.slice(0, -2) : `function() ${call} end`})
  end)`;

const loop = (seconds: string, call: string) => code`
  LoopAsync(${seconds} * 1000, function()
      ExecuteInGameThread(${call})
      return false -- keep looping
  end)`;

function weaponMode(c: Ctx): Mode {
  const { n } = c;
  return {
    file: "weapon",
    local: "Weapon",
    summary: "Retunes the weapon's DT_ItemDataTable row and rewrites FPalDamageInfo on hit.",
    needs: [],
    defs: [
      ["itemId", lit(pickWeapon(c.text)), "DT_ItemDataTable row this mod retunes"],
      ["attackBonus", String(Math.round(n.power * 3)), "flat PhysicalAttackValue added to the row"],
      ["critChance", String(n.chance), "chance per hit to crit"],
      ["critMultiplier", (1.5 + n.intensity / 2).toFixed(2), "damage multiplier on a crit"],
      ["chargeMultiplier", (1.4 + n.power / 10).toFixed(2), "multiplier for the first hit after charging"],
      ["cooldown", String(n.cooldown), "seconds between charges"],
      ["abilityKey", lit("F7"), "UE4SS Key name that charges the next shot"],
    ],
    body: code`
      local ITEM_TABLE = "/Game/Pal/DataTable/Item/DT_ItemDataTable.DT_ItemDataTable"
      local state = { charged = false, readyAt = 0, baseAttack = nil }

      --- FindRow hands back a live reference into the DataTable, so writes apply immediately.
      function M.onWorldReady()
          local dt = StaticFindObject(ITEM_TABLE)
          local row = Fx.valid(dt) and dt:FindRow(Config.itemId)
          if not row then return Fx.log("row %s missing from DT_ItemDataTable", Config.itemId) end
          state.baseAttack = state.baseAttack or row.PhysicalAttackValue
          row.PhysicalAttackValue = state.baseAttack + Config.attackBonus
          Fx.log("%s attack %d -> %d", Config.itemId, state.baseAttack, row.PhysicalAttackValue)
      end

      -- plausible: APalCharacter.ShooterComponent:GetHasWeapon() → APalWeaponBase.ownItemId.StaticId
      local function heldItem(actor)
          local shooter = actor.ShooterComponent
          if not Fx.valid(shooter) then return nil end
          local weapon = shooter:GetHasWeapon()
          return Fx.valid(weapon) and weapon.ownItemId.StaticId:ToString() or nil
      end

      function M.rollCrit(roll, chance)
          return roll < chance
      end

      function M.scale(damage, charged, crit)
          local m = (charged and Config.chargeMultiplier or 1) * (crit and Config.critMultiplier or 1)
          return math.floor(damage * m + 0.5)
      end

      function M.charge(now)
          if now < state.readyAt then
              return Fx.toast(Fx.text("cooldown", "Recharging · %.1fs", state.readyAt - now))
          end
          state.charged, state.readyAt = true, now + Config.cooldown
          Fx.toast(Fx.text("charged", "%s charged", "${c.input.modName}"))
      end

      function M.onDamage(component, info)
          local target, attacker = component:GetOwner(), info.Attacker
          if not Fx.valid(target) or not Fx.isPlayer(attacker) or heldItem(attacker) ~= Config.itemId then return end
          info.NativeDamageValue = M.scale(info.NativeDamageValue, state.charged, M.rollCrit(math.random(), Config.critChance))
          state.charged = false
          ${hit(c, "target", "attacker")}
      end`,
    hooks: [damageHook("Weapon"), keyBind("abilityKey", "Weapon.charge(Fx.now())")].join("\n\n"),
    strings: { ...COOLDOWN, charged: "%s charged" },
    spec: code`
      it("crits only under the chance", function()
          assert.is_true(M.rollCrit(0.01, Config.critChance))
          assert.is_false(M.rollCrit(0.99, Config.critChance))
      end)

      it("stacks charge and crit multipliers", function()
          assert.are.equal(100, M.scale(100, false, false))
          assert.are.equal(math.floor(100 * Config.chargeMultiplier * Config.critMultiplier + 0.5), M.scale(100, true, true))
      end)`,
  };
}

function spellMode(c: Ctx): Mode {
  const { n } = c;
  return {
    file: "spell",
    local: "Spell",
    summary: "A keybound area spell that scales with distance and skips your own pals.",
    needs: ["heal"],
    defs: [
      ["radius", String(n.radius * 100), "spell radius (cm)"],
      ["spellDamage", String(Math.round(n.power * 5)), "damage at the centre (HP)"],
      ["cooldown", String(n.cooldown), "recast time (seconds)"],
      ["castKey", lit("F7"), "UE4SS Key name that casts"],
    ],
    body: code`
      local readyAt = 0

      --- Damage falls off linearly to 35% at the edge of the radius.
      function M.falloff(distance, radius)
          if distance > radius then return 0 end
          return 1 - 0.65 * (distance / radius)
      end

      function M.onWorldReady()
          readyAt = 0
      end

      function M.cast(now)
          local caster = Fx.player()
          if not caster then return end
          if now < readyAt then
              return Fx.toast(Fx.text("cooldown", "Recharging · %.1fs", readyAt - now))
          end
          readyAt = now + Config.cooldown
          local hits = 0
          for _, target in ipairs(Fx.palsNear(caster, Config.radius)) do
              local param = Fx.param(target)
              if param and not Fx.isOwned(param) then
                  Fx.damage(target, Config.spellDamage * M.falloff(Fx.distance(caster, target), Config.radius))
                  ${pulse(c, "target", "caster")}
                  hits = hits + 1
              end
          end
          Fx.toast(Fx.text("cast", "%s · %d hit", "${c.input.modName}", hits))
      end`,
    hooks: keyBind("castKey", "Spell.cast(Fx.now())"),
    strings: { ...COOLDOWN, cast: "%s · %d hit" },
    spec: code`
      it("falls off toward the edge", function()
          assert.are.equal(1, M.falloff(0, 1000))
          assert.is_true(M.falloff(900, 1000) < M.falloff(100, 1000))
          assert.are.equal(0, M.falloff(1200, 1000))
      end)`,
  };
}

function itemMode(c: Ctx): Mode {
  const { n } = c;
  const loot = LOOT.filter((_, i) => (hashStr(c.cls) >> i) & 1).slice(0, 4);
  const entries = (loot.length >= 2 ? loot : ["Wood", "PalSphere", "Money"]).map(
    (id, i) => `{ id = "${id}", weight = ${40 - i * 8}, min = ${id === "Money" ? 50 : 2}, max = ${id === "Money" ? 200 : 6 + i * 2} },`,
  );
  return {
    file: "item",
    local: "Item",
    summary: "A keybound satchel that rolls weighted loot into the player's inventory.",
    needs: ["give"],
    defs: [
      ["lootTable", `{\n${entries.map((e) => `    ${e}`).join("\n")}\n}`, "weighted DT_ItemDataTable rows"],
      ["rolls", String(2 + (n.radius % 3)), "items granted per use"],
      ["maxStack", String(n.health > 500 ? 9999 : 999), "MaxStackCount raised on every lootable row"],
      ["cooldown", String(Math.round(n.cooldown * 20)), "seconds between uses"],
      ["useKey", lit("F7"), "UE4SS Key name that opens the satchel"],
    ],
    body: code`
      local ITEM_TABLE = "/Game/Pal/DataTable/Item/DT_ItemDataTable.DT_ItemDataTable"
      local readyAt = 0

      function M.onWorldReady()
          local dt = StaticFindObject(ITEM_TABLE)
          if not Fx.valid(dt) then return end
          for _, entry in ipairs(Config.lootTable) do
              local row = dt:FindRow(entry.id)
              if row and row.MaxStackCount < Config.maxStack then row.MaxStackCount = Config.maxStack end
          end
      end

      --- Weighted roll; rng is injectable so the spec can pin it.
      function M.roll(entries, rolls, rng)
          rng = rng or math.random
          local total = 0
          for _, e in ipairs(entries) do total = total + e.weight end
          local out = {}
          for _ = 1, rolls do
              local pick, acc = rng() * total, 0
              for _, e in ipairs(entries) do
                  acc = acc + e.weight
                  if pick < acc then
                      out[#out + 1] = { id = e.id, count = e.min + math.floor(rng() * (e.max - e.min + 1)) }
                      break
                  end
              end
          end
          return out
      end

      function M.use(now)
          local player = Fx.player()
          if not player then return end
          if now < readyAt then
              return Fx.toast(Fx.text("cooldown", "Recharging · %.1fs", readyAt - now))
          end
          readyAt = now + Config.cooldown
          for _, drop in ipairs(M.roll(Config.lootTable, Config.rolls)) do
              if Fx.give(drop.id, drop.count) then Fx.toast(Fx.text("loot", "+%d %s", drop.count, drop.id)) end
          end
          ${pulse(c, "player", "player")}
      end`,
    hooks: keyBind("useKey", "Item.use(Fx.now())"),
    strings: { ...COOLDOWN, loot: "+%d %s" },
    spec: code`
      it("rolls the requested number of stacks within bounds", function()
          local drops = M.roll(Config.lootTable, 5, function() return 0.5 end)
          assert.are.equal(5, #drops)
          for _, d in ipairs(drops) do assert.is_true(d.count >= 1) end
      end)

      it("always picks the first entry on a zero roll", function()
          local drops = M.roll(Config.lootTable, 1, function() return 0 end)
          assert.are.equal(Config.lootTable[1].id, drops[1].id)
      end)`,
  };
}

function variantMode(c: Ctx): Mode {
  const { n, pal } = c;
  const [r, g, b] = c.tint;
  return {
    file: "variants",
    local: "Variants",
    summary: `Rolls a rare ${pal.label} variant as wild pals spawn: talents, lucky flag, scale and glow.`,
    needs: ["time"],
    defs: [
      ["basePal", lit(pal.id), `DT_PalMonsterParameter row (${pal.label}); alphas use BOSS_<row>`],
      ["variantChance", String(n.chance), "roll per wild spawn"],
      ["nightBonus", (1 + n.intensity).toFixed(2), "chance multiplier between dusk and dawn"],
      ["minTalent", String(60 + (n.xp % 30)), "floor for Talent_HP / Talent_Melee / Talent_Shot (IVs, 0-100)"],
      ["rank", String(2 + (n.radius % 3)), "condenser rank (stars) the variant spawns with"],
      ["scale", (1.1 + n.speed / 2).toFixed(2), "actor scale"],
      ["tint", `{ R = ${r}, G = ${g}, B = ${b} }`, "emissive tint"],
      ["glow", (n.intensity * 4).toFixed(1), "emissive strength"],
    ],
    body: code`
      local variants = {} -- [actor address] = true

      function M.roll(roll, chance, night, nightBonus)
          return roll < chance * (night and nightBonus or 1)
      end

      local function tint(pal)
          local mesh, c = pal.Mesh, Config.tint
          if not Fx.valid(mesh) then return end
          for i = 0, mesh:GetNumMaterials() - 1 do
              local mid = mesh:CreateDynamicMaterialInstance(i, nil, FName("None"))
              if Fx.valid(mid) then
                  -- plausible: emissive vector parameter on Palworld's monster body materials
                  mid:SetVectorParameterValue(FName("EmissiveColor"), { R = c.R * Config.glow, G = c.G * Config.glow, B = c.B * Config.glow, A = 1 })
              end
          end
      end

      --- MaxHP derives from level, Talent_HP and Rank, so raise those first and heal to the new max.
      function M.apply(pal, param)
          local save = param.SaveParameter
          save.IsRarePal = true -- lucky sparkle and capture fanfare
          save.Rank = math.max(save.Rank, Config.rank)
          save.Talent_HP = math.max(save.Talent_HP, Config.minTalent)
          save.Talent_Melee = math.max(save.Talent_Melee, Config.minTalent)
          save.Talent_Shot = math.max(save.Talent_Shot, Config.minTalent)
          param:SetHP(param:GetMaxHP())
          pal:SetActorScale3D({ X = Config.scale, Y = Config.scale, Z = Config.scale })
          tint(pal)
          variants[pal:GetAddress()] = true
          Fx.toast(Fx.text("variant", "A rare %s (Lv %d) appeared nearby", Fx.palName(pal), param:GetLevel()))
      end

      function M.onWorldReady()
          variants = {}
      end

      --- NotifyOnNewObject fires mid-construction, before the individual parameter is bound,
      --- so the roll waits a beat and re-validates on the game thread.
      function M.onSpawn(pal)
          ExecuteWithDelay(1500, function()
              ExecuteInGameThread(function()
                  if not Fx.valid(pal) or Fx.isPlayer(pal) then return end
                  local param = Fx.param(pal)
                  if not param then return end
                  local id = param.SaveParameter.CharacterID:ToString()
                  if id ~= Config.basePal and id ~= "BOSS_" .. Config.basePal then return end
                  if param.SaveParameter.IsRarePal then
                      if Fx.isOwned(param) then tint(pal) end -- caught variants keep their glow
                      return
                  end
                  if not Fx.isOwned(param) and M.roll(math.random(), Config.variantChance, Fx.isNight(), Config.nightBonus) then
                      M.apply(pal, param)
                  end
              end)
          end)
      end

      --- Variant attacks carry the mod's effects.
      function M.onDamage(component, info)
          local attacker = info.Attacker
          if not Fx.valid(attacker) or not variants[attacker:GetAddress()] then return end
          local target = component:GetOwner()
          ${hit(c, "target", "attacker")}
      end`,
    hooks: [
      code`
        NotifyOnNewObject("/Script/Pal.PalCharacter", function(pal)
            Variants.onSpawn(pal)
        end)`,
      damageHook("Variants"),
    ].join("\n\n"),
    strings: { variant: "A rare %s (Lv %d) appeared nearby" },
    spec: code`
      it("rolls under the chance by day", function()
          assert.is_true(M.roll(Config.variantChance / 2, Config.variantChance, false, Config.nightBonus))
          assert.is_false(M.roll(Config.variantChance * 1.01, Config.variantChance, false, Config.nightBonus))
      end)

      it("rolls more often at night", function()
          assert.is_true(M.roll(Config.variantChance * 1.01, Config.variantChance, true, Config.nightBonus))
      end)`,
  };
}

function companionMode(c: Ctx): Mode {
  const { n } = c;
  return {
    file: "companion",
    local: "Companion",

      ["featuredPal", lit(pal.id), `the ${pal.label} the night stage tracks`],
      [
        "stages",
        `{\n    { id = "level", goal = ${10 + (n.xp % 15)}, reward = { id = "PalSphere_Mega", count = 5 } },\n    { id = "night_watch", goal = ${n.duration * 15}, reward = { id = "Money", count = ${n.health} } },\n    { id = "camp", goal = ${4 + (n.radius % 5)}, reward = { id = "PalSphere_Giga", count = 3 } },\n}`,
        "stage goals: player level, seconds near the featured pal at night, workers in camp",
      ],
      ["watchRadius", String(n.radius * 400), "how close (cm) counts as near the featured pal"],
      ["interval", "5", "seconds between objective checks"],
      ["journalKey", lit("F6"), "Ctrl + this key shows the journal"],
    ],
    body: code`
      local SAVE = "quest_log.lua"
      local log = { stage = 1, value = 0 }

      --- Pure: applies one tick of facts; returns the index of a stage completed this tick.
      function M.advance(state, facts, dt)
          local stage = Config.stages[state.stage]
          if not stage then return nil end
          if stage.id == "level" then
              state.value = facts.level
          elseif stage.id == "night_watch" then
              if facts.nearFeaturedAtNight then state.value = state.value + dt end
          elseif stage.id == "camp" then
              state.value = facts.workers
          end
          if state.value < stage.goal then return nil end
          local done = state.stage
          state.stage, state.value = state.stage + 1, 0
          return done
      end

      local function facts(player)
          local param = Fx.param(player)
          if not param then return nil end
          local near = false
          if Fx.isNight() then
              for _, p in ipairs(Fx.palsNear(player, Config.watchRadius)) do
                  if Fx.palId(p) == Config.featuredPal then near = true break end
              end
          end
          local workers = 0
          for _, p in ipairs(FindAllOf("PalCharacter") or {}) do
              local pp = p:IsValid() and not Fx.isPlayer(p) and Fx.param(p)
              if pp and Fx.isOwned(pp) and Fx.inCamp(p) then workers = workers + 1 end
          end
          return { level = param:GetLevel(), nearFeaturedAtNight = near, workers = workers }
      end

      function M.onWorldReady()
          log = Fx.load(SAVE) or log
      end

      function M.tick()
          local player = Fx.player()
          local f = player and facts(player)
          if not f then return end
          local done = M.advance(log, f, Config.interval)
          if not done then return end
          local stage = Config.stages[done]
          Fx.give(stage.reward.id, stage.reward.count)
          Fx.toast(Fx.text("stage_done", "${c.input.modName} · %s complete", Fx.text(stage.id, stage.id)))
          for _, foe in ipairs(Fx.palsNear(player, 1500)) do
              local fp = Fx.param(foe)
              if fp and not Fx.isOwned(fp) then
                  ${pulse(c, "foe", "player")}
              end
          end
          Fx.save(SAVE, log)
      end

      function M.journal()
          local stage = Config.stages[log.stage]
          if not stage then return Fx.toast(Fx.text("finished", "${c.input.modName} · all stages complete")) end
          Fx.toast(Fx.text("progress", "%s · %d / %d", Fx.text(stage.id, stage.id), math.floor(log.value), stage.goal))
      end`,
    hooks: [
      loop("Config.interval", "Quests.tick"),
      keyBind("journalKey", "Quests.journal()", true),
      code`
        -- Typing !quest in chat opens the journal too.
        RegisterHook("/Script/Pal.PalPlayerState:EnterChat_Receive", function(self, message)
            if message:get().Message:ToString():lower() == "!quest" then
                ExecuteInGameThread(Quests.journal)
            end
        end)`,
    ].join("\n\n"),
    strings: {
      level: "Reach the trainer's level",
      night_watch: `Shadow a ${pal.label} after dark`,
      camp: "Staff your base",
      stage_done: `${c.input.modName} · %s complete`,
      progress: "%s · %d / %d",
      finished: `${c.input.modName} · all stages complete`,
    },
    spec: code`
      it("completes the level stage once the player reaches the goal", function()
          local state = { stage = 1, value = 0 }
          assert.is_nil(M.advance(state, { level = 1, workers = 0 }, 5))
          assert.are.equal(1, M.advance(state, { level = Config.stages[1].goal, workers = 0 }, 5))
          assert.are.equal(2, state.stage)
      end)

      it("only counts night-watch time near the featured pal", function()
          local state = { stage = 2, value = 0 }
          M.advance(state, { nearFeaturedAtNight = false }, 5)
          assert.are.equal(0, state.value)
          M.advance(state, { nearFeaturedAtNight = true }, 5)
          assert.are.equal(5, state.value)
      end)`,
  };
}

function overlayMode(c: Ctx): Mode {
  const { n } = c;
  return {
    file: "overlay",
    local: "Overlay",
    summary: "Look at a pal to read its IVs, passives and work speed; pin it to keep it refreshing.",
    needs: [],
    ue: true,
    fx: false,
    defs: [
      ["focusRange", String(n.radius * 500), "max distance (cm) to inspect"],
      ["focusCone", "0.92", "min dot product between view and pal (≈23°)"],
      ["refreshMs", String(n.interval * 250), "pinned refresh rate"],
      ["inspectKey", lit("F7"), "UE4SS Key name that inspects the pal under the crosshair"],
      ["pinKey", lit("F6"), "Ctrl + this key pins / unpins the overlay"],
    ],
    body: code`
      local pinned, lastFocus = false, nil

      --- Pure: the candidate closest to the view ray inside the cone, nearer ones winning ties.
      function M.pickFocus(eye, forward, candidates, maxDistance, minDot)
          local best, bestScore
          for _, c in ipairs(candidates) do
              local dx, dy, dz = c.pos.X - eye.X, c.pos.Y - eye.Y, c.pos.Z - eye.Z
              local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
              if dist > 0 and dist <= maxDistance then
                  local dot = (dx * forward.X + dy * forward.Y + dz * forward.Z) / dist
                  local score = dot - 0.1 * dist / maxDistance
                  if dot >= minDot and (not bestScore or score > bestScore) then best, bestScore = c, score end
              end
          end
          return best
      end

      function M.format(s)
          return {
              string.format("%s  Lv %d%s", s.name, s.level, s.lucky and "  ★" or ""),
              string.format("HP %d/%d · IV %d/%d/%d/%d", s.hp, s.maxHp, s.talentHp, s.talentMelee, s.talentShot, s.talentDefense),
              string.format("Work %d · %s", s.craftSpeed, #s.passives > 0 and table.concat(s.passives, ", ") or "no passives"),
          }
      end

      local function statsOf(pal)
          local param = Fx.param(pal)
          if not param then return nil end
          local save, passives = param.SaveParameter, {}
          save.PassiveSkillList:ForEach(function(_, skill) passives[#passives + 1] = skill:get():ToString() end)
          return {
              name = Fx.palName(pal), level = param:GetLevel(), lucky = save.IsRarePal,
              hp = param:GetHP().Value // 1000, maxHp = param:GetMaxHP().Value // 1000,
              talentHp = save.Talent_HP, talentMelee = save.Talent_Melee, talentShot = save.Talent_Shot, talentDefense = save.Talent_Defense,
              craftSpeed = save.CraftSpeed, passives = passives,
          }
      end

      function M.onWorldReady()
          lastFocus = nil
      end

      function M.inspect()
          local controller = UEHelpers.GetPlayerController()
          local camera = Fx.valid(controller) and controller.PlayerCameraManager
          if not Fx.valid(camera) then return end
          local eye = camera:GetCameraLocation()
          local forward = UEHelpers.GetKismetMathLibrary():GetForwardVector(camera:GetCameraRotation())
          local candidates = {}
          for _, pal in ipairs(FindAllOf("PalCharacter") or {}) do
              if pal:IsValid() and not Fx.isPlayer(pal) then candidates[#candidates + 1] = { actor = pal, pos = pal:K2_GetActorLocation() } end
          end
          local focus = M.pickFocus(eye, forward, candidates, Config.focusRange, Config.focusCone)
          if not focus or (pinned and focus.actor:GetAddress() == lastFocus) then return end
          lastFocus = focus.actor:GetAddress()
          local stats = statsOf(focus.actor)
          if stats then
              for _, line in ipairs(M.format(stats)) do Fx.toast(line) end
          end
      end

      function M.togglePin()
          pinned = not pinned
          lastFocus = nil
          Fx.toast(Fx.text(pinned and "pinned" or "unpinned", pinned and "Overlay pinned" or "Overlay unpinned"))
      end

      function M.isPinned()
          return pinned
      end`,
    hooks: [
      keyBind("inspectKey", "Overlay.inspect()"),
      keyBind("pinKey", "Overlay.togglePin()", true),
      code`
        -- UE4SS 3.x Lua has no draw API, so the overlay rides Palworld's notice feed and refreshes while pinned.
        LoopAsync(Config.refreshMs, function()
            if Overlay.isPinned() then ExecuteInGameThread(Overlay.inspect) end
            return false
        end)`,
    ].join("\n\n"),
    strings: { pinned: "Overlay pinned", unpinned: "Overlay unpinned" },
    spec: code`
      local eye, fwd = { X = 0, Y = 0, Z = 0 }, { X = 1, Y = 0, Z = 0 }

      it("focuses the pal in front of the camera", function()
          local ahead, behind = { pos = { X = 500, Y = 10, Z = 0 } }, { pos = { X = -500, Y = 0, Z = 0 } }
          assert.are.equal(ahead, M.pickFocus(eye, fwd, { behind, ahead }, Config.focusRange, Config.focusCone))
      end)

      it("ignores pals out of range", function()
          assert.is_nil(M.pickFocus(eye, fwd, { { pos = { X = Config.focusRange * 2, Y = 0, Z = 0 } } }, Config.focusRange, Config.focusCone))
      end)

      it("formats a three-line panel", function()
          local lines = M.format({ name = "Lamball", level = 12, lucky = true, hp = 300, maxHp = 410, talentHp = 80, talentMelee = 50, talentShot = 40, talentDefense = 70, craftSpeed = 100, passives = { "CraftSpeed_up1" } })
          assert.are.equal(3, #lines)
          assert.truthy(lines[1]:find("★"))
      end)`,
  };
}

function audioMode(c: Ctx): Mode {
  const { n, cls } = c;
  return {
    file: "music",
    local: "Music",
    summary: "Adaptive Wwise layers that follow combat, nightfall and your base.",
    needs: ["time", "camp"],
    fx: false,
    defs: [
      ["combatWindow", String(Math.round(n.cooldown * 3)), "seconds a hit keeps the combat layer up"],
      ["interval", "1", "seconds between layer checks"],
      [
        "events",
        `{\n    explore = "Play_${cls}_Explore",\n    night = "Play_${cls}_Night",\n    base = "Play_${cls}_Base",\n    combat = "Play_${cls}_Combat",\n    stop = "Stop_${cls}_All",\n}`,
        "Wwise events from the mod's soundbank (Content/Paks/~mods)",
      ],
    ],
    body: code`
      local current, lastHitAt = nil, -math.huge
      local Ak

      --- Pure: layer priority is combat > base > night > explore.
      function M.pickLayer(now, lastHit, night, atBase)
          if now - lastHit < Config.combatWindow then return "combat" end
          if atBase then return "base" end
          if night then return "night" end
          return "explore"
      end

      local function post(event, actor)
          Ak = Ak or StaticFindObject("/Script/AkAudio.Default__AkGameplayStatics")
          if not Fx.valid(Ak) then return Fx.log("AkAudio not loaded") end
          -- plausible: PostEventByName on the shipped Wwise integration; newer ones post a UAkAudioEvent
          pcall(function() Ak:PostEventByName(event, actor, false) end)
      end

      function M.onWorldReady()
          current = nil
      end

      function M.onDamage(component, info)
          if Fx.isPlayer(component:GetOwner()) or Fx.isPlayer(info.Attacker) then lastHitAt = Fx.now() end
      end

      function M.tick()
          local player = Fx.player()
          if not player then return end
          local layer = M.pickLayer(Fx.now(), lastHitAt, Fx.isNight(), Fx.inCamp(player))
          if layer == current then return end
          if current then post(Config.events.stop, player) end
          post(Config.events[layer], player)
          Fx.log("%s", Fx.text("now_playing", "music -> %s", layer))
          current = layer
      end`,
    hooks: [damageHook("Music"), loop("Config.interval", "Music.tick")].join("\n\n"),
    strings: { now_playing: "music -> %s" },
    spec: code`
      it("prioritises combat over everything", function()
          assert.are.equal("combat", M.pickLayer(10, 9, true, true))
      end)

      it("falls back through base, night and explore", function()
          local old = -1000
          assert.are.equal("base", M.pickLayer(10, old, true, true))
          assert.are.equal("night", M.pickLayer(10, old, true, false))
          assert.are.equal("explore", M.pickLayer(10, old, false, false))
      end)`,
  };
}

function postFxMode(c: Ctx): Mode {
  const { n } = c;
  const [r, g, b] = c.tint;
  return {
    file: "postprocess",
    local: "PostFx",
    summary: "Overrides the unbound PostProcessVolume and blends a day and night grade by the hour.",
    needs: ["time"],
    fx: false,
    defs: [
      ["intensity", String(n.intensity), "overall strength (0-2)"],
      ["tint", `{ R = ${r}, G = ${g}, B = ${b} }`, "ColorGain tint"],
      ["filmGrain", (n.chance / 2).toFixed(2), "FilmGrainIntensity"],
      ["refreshSeconds", "10", "how often the grade follows the clock"],
      ["toggleKey", lit("F8"), "UE4SS Key name that toggles the grade"],
    ],
    body: code`
      local enabled = true
      local DAY = { bloom = ${(0.4 + n.intensity / 3).toFixed(2)}, vignette = 0.25, saturation = ${(1 + n.speed / 2).toFixed(2)}, exposure = 0.0 }
      local NIGHT = { bloom = ${(1 + n.intensity).toFixed(2)}, vignette = 0.55, saturation = 0.85, exposure = ${(-n.speed).toFixed(2)} }

      --- 0 at midday, 1 from 21:00 to 03:00, ramping through dusk and dawn.
      function M.nightFactor(hour)
          if hour >= 21 or hour < 3 then return 1 end
          if hour >= 17 then return (hour - 17) / 4 end
          if hour < 7 then return 1 - (hour - 3) / 4 end
          return 0
      end

      function M.blend(a, b, t)
          local out = {}
          for k, v in pairs(a) do out[k] = v + (b[k] - v) * t end
          return out
      end

      local function apply(volume, grade)
          local s, k = volume.Settings, Config.intensity
          s.bOverride_BloomIntensity, s.BloomIntensity = enabled, grade.bloom * k
          s.bOverride_VignetteIntensity, s.VignetteIntensity = enabled, grade.vignette * k
          s.bOverride_AutoExposureBias, s.AutoExposureBias = enabled, grade.exposure
          s.bOverride_FilmGrainIntensity, s.FilmGrainIntensity = enabled, Config.filmGrain
          s.bOverride_ColorSaturation = enabled
          s.ColorSaturation = { X = grade.saturation, Y = grade.saturation, Z = grade.saturation, W = 1 }
          s.bOverride_ColorGain = enabled
          s.ColorGain = { X = 1 + (Config.tint.R - 1) * 0.3 * k, Y = 1 + (Config.tint.G - 1) * 0.3 * k, Z = 1 + (Config.tint.B - 1) * 0.3 * k, W = 1 }
      end

      --- Only unbound volumes carry the global grade; local ones (caves, dungeons) are left alone.
      function M.refresh()
          local grade = M.blend(DAY, NIGHT, M.nightFactor(Fx.hour()))
          for _, volume in ipairs(FindAllOf("PostProcessVolume") or {}) do
              if volume:IsValid() and volume.bUnbound then apply(volume, grade) end
          end
      end

      M.onWorldReady = M.refresh

      function M.toggle()
          enabled = not enabled
          M.refresh()
          Fx.toast(Fx.text(enabled and "grade_on" or "grade_off", enabled and "Grade on" or "Grade off"))
      end`,
    hooks: [
      code`
        NotifyOnNewObject("/Script/Engine.PostProcessVolume", function()
            ExecuteWithDelay(1000, function() ExecuteInGameThread(PostFx.refresh) end)
        end)`,
      loop("Config.refreshSeconds", "PostFx.refresh"),
      keyBind("toggleKey", "PostFx.toggle()"),
      code`
        RegisterConsoleCommandHandler("${c.snake}", function(_, parameters, outputDevice)
            Config.intensity = tonumber(parameters[1]) or Config.intensity
            ExecuteInGameThread(PostFx.refresh)
            outputDevice:Log(string.format("[${c.cls}] intensity %.2f", Config.intensity))
            return true
        end)`,
    ].join("\n\n"),
    strings: { grade_on: "Grade on", grade_off: "Grade off" },
    spec: code`
      it("is fully night at midnight and day at noon", function()
          assert.are.equal(1, M.nightFactor(0))
          assert.are.equal(0, M.nightFactor(12))
      end)

      it("blends halfway at dusk", function()
          local g = M.blend({ bloom = 0 }, { bloom = 2 }, M.nightFactor(19))
          assert.are.equal(1, g.bloom)
      end)`,
  };
}

/* ───────────── assembly ───────────── */

const EXPEDITION = /expedition|idle pals?|loot runs?|dispatch|scouting|errand|forag/;

function modeFor(c: Ctx): Mode {
  const k = c.input.category.key;
  // "Loot" routes expedition boards to Items; the prompt still describes a base system.
  if ((k === "items" || k === "mechanics") && EXPEDITION.test(c.text)) return expeditionMode(c);
  switch (ARCH[k]) {
    case "item":
      return k === "weapons" ? weaponMode(c) : k === "magic" ? spellMode(c) : itemMode(c);
    case "entity":
      return k === "vehicles" ? mountMode(c) : k === "characters" ? companionMode(c) : variantMode(c);
    case "world":
      return spawnsMode(c);
    case "visual":
      return postFxMode(c);
    default:
      if (k === "quests") return questMode(c);
      if (k === "interface") return overlayMode(c);
      if (k === "audio") return audioMode(c);
      return worksiteMode(c);
  }
}

const tableLines = (defs: Def[]) => defs.map(([k, v, note]) => (v.includes("\n") ? `-- ${note}\n${k} = ${v},` : `${k} = ${v}, -- ${note}`));

export function palworldUE4SS(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const effects = effectsFor(input);
  const fx = effects.map((e) => e.key);
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  const c: Ctx = { input, n, cls, snake, fx, tint: effects[0].tint, pal: pickPal(input, fx), text };
  const mode = modeFor(c);
  const usesFx = mode.fx !== false;
  const needs = new Set([...mode.needs, ...(usesFx ? fx.flatMap((k) => FX[k].needs) : [])]);
  const own = new Set(mode.defs.map(([k]) => k));
  // Effect tunables only ship when a snippet in this module actually reads them.
  const defs = [...mode.defs, ...(usesFx ? fxDefs(fx, n, c.pal.id).filter(([k]) => !own.has(k) && mode.body.includes(`Config.${k}`)) : [])];
  const strings: Record<string, string> = { ...mode.strings, ...(usesFx && fx.includes("neon") ? { hit: "%s  -%d", pulse: "%s ▸ surge" } : {}) };
  const local = mode.local;
  const vNote = input.version > 1 ? `-- v${input.version}: retuned numbers${input.model !== "katara" ? ", all exposed in config.lua" : ""}` : "";

  const main = file(
    "Scripts/main.lua",
    code`
      --[[
          ${input.modName}
          ${input.category.label} mod for Palworld · RE-UE4SS 3.x (Lua 5.4)
          Forged by Cyrus (${MODEL_NAME[input.model]}) · v${input.version}
          ${usesFx ? `Effects: ${effects.map((e) => e.label.toLowerCase()).join("; ")}` : ""}
      ]]
      ${vNote}

      local Fx = require("${snake}.effects")
      local ${local} = require("${snake}.${mode.file}")

      local Config = Fx.loadConfig(${local}.DEFAULTS)
      ${local}.init(Config)

      -- ClientRestart fires whenever the local pawn is (re)possessed: first load, respawn, world travel.
      RegisterHook("/Script/Engine.PlayerController:ClientRestart", function(self)
          local controller = self:get()
          if not Fx.valid(controller) or not controller:IsLocalController() then return end
          ExecuteWithDelay(2000, function()
              ExecuteInGameThread(${local}.onWorldReady)
          end)
      end)

      ${mode.hooks}

      Fx.log("v${input.version} loaded (${ARCH[input.category.key]} · ${mode.file})")`,
  );

  const core = file(
    `Scripts/${snake}/${mode.file}.lua`,
    code`
      --[[
          ${input.modName} · ${mode.file}.lua
          ${mode.summary}
      ]]
      ${mode.ue ? 'local UEHelpers = require("UEHelpers")' : ""}
      local Fx = require("${snake}.effects")

      local M = {}
      local Config = {}

      M.DEFAULTS = {
          ${tableLines(defs)}
      }

      function M.init(config)
          Config = config
      end

      ${mode.body}

      return M`,
  );

  const config = file(
    `Scripts/${snake}/config.lua`,
    code`
      -- ${input.modName} · config.lua
      -- Overrides for ${mode.file}.lua; delete a line to fall back to its default.
      -- Save, then hot-reload with Ctrl+R in the UE4SS console (or restart the game).
      return {
          ${tableLines(defs)}
          language = "en", -- loads lang/<language>.lua
      }`,
  );

  const l10n = file(
    `Scripts/${snake}/lang/en.lua`,
    code`
      -- ${input.modName} · English strings.
      -- Copy to lang/<code>.lua to translate, then set language in config.lua. Keep the % placeholders.
      return {
          name = ${lit(input.modName)},
          ${Object.entries(strings).map(([k, v]) => `${k} = ${lit(v)},`)}
      }`,
  );

  const test = file(
    `spec/${snake}_spec.lua`,
    code`
      -- busted spec for ${input.modName} · run \`busted\` from the mod folder
      package.path = "./Scripts/?.lua;" .. package.path

      -- Just enough UE4SS surface for the modules to load outside the game.
      _G.RegisterHook = function() end
      _G.NotifyOnNewObject = function() end
      _G.RegisterKeyBind = function() end
      _G.LoopAsync = function() end
      _G.ExecuteWithDelay = function(_, fn) fn() end
      _G.ExecuteInGameThread = function(fn) fn() end
      _G.StaticFindObject = function() return nil end
      _G.FindFirstOf = function() return nil end
      _G.FindAllOf = function() return nil end
      _G.FName = function(s) return s end
      package.preload["UEHelpers"] = function()
          return { GetPlayerController = function() return nil end, GetWorld = function() return nil end }
      end

      local Fx = require("${snake}.effects")
      local M = require("${snake}.${mode.file}")
      local Config = Fx.loadConfig(M.DEFAULTS)
      M.init(Config)

      describe("${input.modName}", function()
          ${mode.spec}

          it("ships non-negative numeric defaults", function()
              for key, value in pairs(M.DEFAULTS) do
                  if type(value) == "number" then assert.is_true(value >= 0, key) end
              end
          end)
      end)`,
  );

  const files: ModFile[] = [main, core, file(`Scripts/${snake}/effects.lua`, effectsModule(input, snake, cls, needs)), file("enabled.txt", "")];
  return { files, config, l10n, test };
}

