export interface ForgeRequest {
  prompt: string;
  model: ModelId;
  images?: number;
  /** User-added game branches, so prompts can route to them too. */
  games?: Game[];
  context?: {
    gameId?: GameId;
    category?: CategoryKey;
    modId?: string;
    modName?: string;
    version?: number;
  };
}

/* ───────────── Routing: which branch of the network does this prompt belong to? ───────────── */

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const hasWord = (text: string, word: string) => new RegExp(`(^|[^a-z0-9])${escapeRe(word)}(s|es)?([^a-z0-9]|$)`).test(text);

export function routePrompt(
  prompt: string,
  ctx: ForgeRequest["context"] = {},
  games: Game[] = GAMES,
): { gameId: GameId; category: CategoryKey } {
  const p = prompt.toLowerCase();
  const byId = (id: GameId) => games.find((g) => g.id === id) ?? GAMES[0];

  let gameId: GameId | undefined;
  let bestGame = 0;
  for (const g of games) {
    for (const alias of g.aliases) {
      if (hasWord(p, alias) && alias.length > bestGame) {
        bestGame = alias.length;
        gameId = g.id;
      }
    }
  }
  // A game named in the prompt wins over the focused branch; aliases like "farm" only count when nothing is focused.
  const strongMention = gameId && byId(gameId).aliases.slice(0, 2).some((a) => hasWord(p, a));
  if (ctx?.gameId && !strongMention) gameId = ctx.gameId;
  gameId ??= "minecraft";

  let category: CategoryKey | undefined;
  let bestCat = 0;
  for (const c of CATEGORIES) {
    let score = 0;
    for (const k of c.keywords) if (hasWord(p, k)) score += k.length;
    if (score > bestCat) {
      bestCat = score;
      category = c.key;
    }
  }
  if (!category || (ctx?.category && bestCat < 4)) category = ctx?.category ?? category;
  category ??= byId(gameId).categories[0];

  return { gameId, category };
}

/* ───────────── Naming ───────────── */

const LEAD = /^(please\s+)?(can you\s+|could you\s+)?(make|create|build|add|design|forge|generate|write|give)( me| us)?\s+/i;
const STOP_CLAUSE = /\b(for|in|that|which|who|where|with|so|to|when|while|and|but|using|inside|into|on)\b/i;
const FILLER = new Set(["a", "an", "the", "some", "new", "mod", "cool", "awesome", "i", "want", "need", "like", "really"]);
const FLAVOR: [RegExp, string][] = [
  [/fire|flame|burn|ember|lava/, "Ember"],
  [/frost|ice|freez|snow|cold/, "Frost"],
  [/lightning|storm|thunder|shock/, "Storm"],
  [/shadow|dark|void|night/, "Void"],
  [/moon|lunar|star|cosmic|nebula/, "Lunar"],
  [/neon|cyber|hack|chrome/, "Neon"],
  [/nature|leaf|grow|forest|crop/, "Verdant"],
];

function titleCase(word: string) {
  if (word.length > 1 && word === word.toUpperCase()) return word;
  return word
    .split("-")
    .map((w) => (w ? w[0].toUpperCase() + w.slice(1).toLowerCase() : w))
    .join("-");
}

export function deriveModName(prompt: string, game: Game, category: CategoryKey): string {
  let text = prompt.trim().replace(LEAD, "");
  // Strip only names of the game itself ("for Minecraft"), not thematic aliases like "cyberdeck".
  for (const alias of [...game.aliases.slice(0, 3), game.name].sort((a, b) => b.length - a.length)) {
    text = text.replace(new RegExp(`\\b${escapeRe(alias)}\\b`, "ig"), " ");
  }
  const head = text.split(STOP_CLAUSE)[0] ?? text;
  const words = head
    .replace(/[^\p{L}\p{N}\s-]/gu, " ")
    .split(/\s+/)
    .filter((w) => w && !FILLER.has(w.toLowerCase()));

  let picked = words.slice(0, 4).map(titleCase);
  if (picked.length === 1) {
    const flavor = FLAVOR.find(([re]) => re.test(prompt.toLowerCase()))?.[1];
    if (flavor && flavor.toLowerCase() !== picked[0].toLowerCase()) picked = [flavor, ...picked];
  }
  let name = picked.join(" ");
  if (!name) name = `${FLAVOR.find(([re]) => re.test(prompt.toLowerCase()))?.[1] ?? "Astral"} ${CATEGORY_BY_KEY[category].label.replace(/s$/, "")}`;
  if (name.length > 34) name = name.slice(0, 34).replace(/\s+\S*$/, "");
  return name;
}

/* ───────────── Thinking plan ───────────── */

const API_SURFACE: Partial<Record<GameId, string>> = {
  minecraft: "Fabric registries · item settings · LivingEntity hooks",
  palworld: "UE4SS RegisterHook · FindAllOf · Pal parameter tables",
  rust: "Oxide hooks · chat commands · permissions",
  valheim: "BepInEx plugin · Harmony patches · ZNetScene prefabs",
  zomboid: "Lua Events · item scripts · sandbox options",
  terraria: "ModItem · ModNPC · ModSystem hooks",
};

export interface ThinkStep {
  label: string;
  detail: string;
  ms: number;
}

export function planThinking(input: TemplateInput, files: ModFile[], refining: boolean): ThinkStep[] {
  const { game, category, model, prompt, version } = input;
  const features = deriveFeatures(input);
  const short = prompt.length > 54 ? `${prompt.slice(0, 54).trim()}…` : prompt;
  const steps: ThinkStep[] = [
    { label: refining ? "Reading the current build" : "Parsing intent", detail: `“${short}” → ${features.length} mechanics`, ms: 700 },
    { label: "Routing through the core", detail: `Cyrus Core › ${game.name} › ${category.label}`, ms: 650 },
  ];
  if (model !== "katara") {
    steps.push({ label: `Mapping ${game.short} API surface`, detail: API_SURFACE[game.id] ?? `${game.toolchain} · events · content hooks`, ms: 800 });
    steps.push({ label: "Designing mechanics", detail: features.slice(0, 2).join(" · "), ms: 850 });
  }
  if (model === "yakko") {
    steps.push({ label: "Exploring alternatives", detail: "3 architectures considered → event-driven wins", ms: 1000 });
    steps.push({ label: "Stress-testing edge cases", detail: "multiplayer sync · save/load · mod conflicts", ms: 950 });
    steps.push({ label: "Balancing numbers", detail: "simulated 400 encounters against vanilla curves", ms: 900 });
  }
  steps.push({ label: `Scaffolding ${files.length} files`, detail: `${game.toolchain} · v${version}`, ms: 600 });
  return steps;
}

/* ───────────── Versions & diffs ───────────── */

export function diffStats(prev: ModFile[] | undefined, next: ModFile[]) {
  const count = (files: ModFile[]) => {
    const m = new Map<string, number>();
    for (const f of files) for (const line of f.content.split("\n")) if (line.trim()) m.set(line, (m.get(line) ?? 0) + 1);
    return m;
  };
  const a = count(prev ?? []);
  const b = count(next);
  let additions = 0;
  let deletions = 0;
  for (const [line, n] of b) additions += Math.max(0, n - (a.get(line) ?? 0));
  for (const [line, n] of a) deletions += Math.max(0, n - (b.get(line) ?? 0));
  return { additions, deletions };
}

function hash(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

const SEED_PROMPTS = [
  (m: Mod) => `${m.name}: ${m.summary}`,
  () => "Balance pass — expose config and tune the numbers",
  () => "Add tests, docs and a changelog",
];
const SEED_MODELS: ModelId[] = ["katara", "saka", "yakko"];

/** Builds the version history for a seed mod. Deterministic so it matches across reloads. */
export function seedVersions(mod: Mod): ModVersion[] {
  const count = 1 + (hash(mod.id) % 3);
  const game = GAME_BY_ID[mod.gameId];
  const category = CATEGORY_BY_KEY[mod.category];
  const versions: ModVersion[] = [];
  let prev: ModFile[] | undefined;
  for (let v = 1; v <= count; v++) {
    const model = SEED_MODELS[v - 1];
    const prompt = SEED_PROMPTS[v - 1](mod);
    const files = buildModFiles({ game, category, modName: mod.name, prompt: `${mod.name}: ${mod.summary}`, model, version: v });
    const { additions, deletions } = diffStats(prev, files);
    versions.push({
      id: `${mod.id}@v${v}`,
      label: `v${v}`,
      createdAt: mod.createdAt + (v - 1) * 3_600_000 * 5,
      model,
      credits: MODEL_BY_ID[model].credits,
      prompt,
      summary: v === 1 ? mod.summary : prompt,
      files,
      additions,
      deletions,
    });
    prev = files;
  }
  return versions;
}

/* ───────────── The forge stream (server side) ───────────── */

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const rand = (a: number, b: number) => a + Math.random() * (b - a);

export async function* forgeStream(req: ForgeRequest, signal?: AbortSignal): AsyncGenerator<GenEvent> {
  const model = MODEL_BY_ID[req.model] ?? MODEL_BY_ID.katara;
  const prompt = req.prompt.trim().slice(0, 2000);
  const ctx = req.context ?? {};
  const refining = Boolean(ctx.modId && ctx.modName);

  const jobId = `job_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  yield { type: "start", jobId, model: model.id, credits: model.credits };
  await sleep(320);

  const games = [...GAMES, ...(req.games ?? [])];
  const route = refining && ctx.gameId && ctx.category ? { gameId: ctx.gameId, category: ctx.category } : routePrompt(prompt, ctx, games);
  const game = games.find((g) => g.id === route.gameId) ?? GAMES[0];
  const category = CATEGORY_BY_KEY[route.category];
  const modName = refining ? ctx.modName! : deriveModName(prompt, game, route.category);
  const version = refining ? Math.max(2, ctx.version ?? 2) : 1;
  const modId = refining ? ctx.modId! : `${route.gameId}-${slugify(modName) || "mod"}-${Math.random().toString(36).slice(2, 6)}`;

  const input: TemplateInput = { game, category, modName, prompt, model: model.id, version };
  const files = buildModFiles(input);
  const features = deriveFeatures(input);
  const steps = planThinking(input, files, refining);

  // First two steps happen before we know the branch — that's when the core is "thinking".
  for (let i = 0; i < steps.length; i++) {
    if (signal?.aborted) return;
    const s = steps[i];
    const id = `s${i}`;
    yield { type: "think", id, label: s.label, detail: s.detail };
    if (i === 1) {
      yield {
        type: "route",
        gameId: game.id,
        category: category.key,
        modName,
        modId,
        summary: refining ? prompt : features[0] ?? category.description,
        tags: features.slice(0, 3).map((f) => f.split(" ").slice(0, 2).join(" ").toLowerCase()),
      };
    }
    await sleep(s.ms * rand(0.75, 1.15) + (model.id === "yakko" ? 250 : 0));
    yield { type: "think-done", id };
  }

  for (let fi = 0; fi < files.length; fi++) {
    const f = files[fi];
    const id = `w${fi}`;
    yield { type: "think", id, label: `Writing ${f.path.split("/").pop()}`, detail: f.path };
    yield { type: "file", path: f.path, language: f.language };
    const content = f.content;
    // Supporting files stream faster than the main source file.
    const boost = fi === 0 ? 1 : 1.8;
    let i = 0;
    while (i < content.length) {
      if (signal?.aborted) return;
      const size = Math.round(rand(model.chunk[0], model.chunk[1]) * boost);
      yield { type: "chunk", path: f.path, text: content.slice(i, i + size) };
      i += size;
      await sleep(model.tick * rand(0.6, 1.4));
    }
    yield { type: "file-done", path: f.path };
    yield { type: "think-done", id };
    await sleep(160);
  }

  const pid = "pkg";
  yield { type: "think", id: pid, label: "Packaging & signing", detail: `${modName} v${version} · ${files.length} files` };
  await sleep(520);
  yield { type: "think-done", id: pid };

  yield {
    type: "done",
    summary: refining ? prompt : features.join(" · "),
    notes: buildModNotes(input),
  };
}

// Cyrus game registry (client-safe, data only). Adding a game = adding a row here; the home
// game selector, the version picker and the copy all read from it. No official logos or art:
// each game gets a neutral two-letter text mark.
import { MB_VERSIONS, MB_DEFAULT_VERSION } from "../modbuilder/types";

export type CyrusGameStatus = "live" | "soon";

export type CyrusGame = {
  id: string;
  name: string;
  status: CyrusGameStatus;
  /** two-letter text mark drawn in a neutral tile */
  mark: string;
  /** what Cyrus builds for it, customer voice */
  builds: string;
  /** server software the mods target (shown next to the version) */
  loader: string;
  /** supported server versions, newest first */
  versions: readonly string[];
  defaultVersion?: string;
  /** legacy flag, true when status === "live" */
  available: boolean;
  note: string;
};

const g = (x: Omit<CyrusGame, "available" | "note">): CyrusGame => ({ ...x, available: x.status === "live", note: x.status === "live" ? x.builds : "Coming soon" });

export const CYRUS_GAMES: CyrusGame[] = [
  g({ id: "minecraft", name: "Minecraft", status: "live", mark: "MC", builds: "Paper and Purpur server plugins", loader: "Paper", versions: MB_VERSIONS, defaultVersion: MB_DEFAULT_VERSION }),
  g({ id: "ark", name: "ARK", status: "soon", mark: "AR", builds: "ARK: Survival Ascended server mods", loader: "ASA", versions: [] }),
  g({ id: "theisle", name: "The Isle", status: "soon", mark: "TI", builds: "The Isle Evrima server mods", loader: "Evrima", versions: [] }),
  g({ id: "palworld", name: "Palworld", status: "soon", mark: "PW", builds: "UE4SS server mods", loader: "UE4SS", versions: [] }),
  g({ id: "rust", name: "Rust", status: "soon", mark: "RS", builds: "Oxide / Carbon plugins", loader: "Oxide", versions: [] }),
  g({ id: "valheim", name: "Valheim", status: "soon", mark: "VH", builds: "BepInEx server mods", loader: "BepInEx", versions: [] }),
];

export const CYRUS_DEFAULT_GAME = CYRUS_GAMES.find((x) => x.status === "live")!;
export const cyrusGame = (id: string | null | undefined) => CYRUS_GAMES.find((x) => x.id === id) ?? CYRUS_DEFAULT_GAME;
/** "1.20.4 – 1.21.11" */
export const versionRange = (game: CyrusGame) => (game.versions.length ? (game.versions.length > 1 ? `${game.versions[game.versions.length - 1]} – ${game.versions[0]}` : game.versions[0]) : "");
/**
 * The template toolkit shared by every game's code generator: the indentation-aware `code` tag,
 * seeded numbers, mod naming, effects parsed from the prompt and the feature list.
 */
import type { CategoryKey, CategoryMeta, CodeLanguage, Game, ModelId, ModFile } from "@/lib/cyrus/types";

export interface TemplateInput {
  game: Game;
  category: CategoryMeta;
  modName: string;
  prompt: string;
  model: ModelId;
  version: number;
}

/* ───────────── utilities ───────────── */

const EMPTY = "\u0000";

/**
 * Indentation-aware template tag: strips the common indent, re-indents multi-line
 * interpolations to the placeholder's column and drops lines whose only content was
 * an empty interpolation.
 */
export function code(strings: TemplateStringsArray, ...vals: unknown[]): string {
  let out = "";
  strings.forEach((s, i) => {
    out += s;
    if (i >= vals.length) return;
    const v = vals[i];
    let str = Array.isArray(v)
      ? v.filter((x) => x !== false && x != null && x !== "").map((x) => String(x).replace(/\n+$/, "")).join("\n")
      : v === false || v == null || v === ""
        ? ""
        : String(v).replace(/\n+$/, "");
    if (!str) str = EMPTY;
    const lineStart = out.slice(out.lastIndexOf("\n") + 1);
    const indent = lineStart.match(/^[ \t]*/)![0];
    out += str
      .split("\n")
      .map((l, j) => (j === 0 || !l ? l : indent + l))
      .join("\n");
  });
  const lines = out
    .replace(/^\n/, "")
    .split("\n")
    .filter((l) => l.trim() !== EMPTY)
    .map((l) => l.replaceAll(EMPTY, ""));
  while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
  const min = Math.min(...lines.filter((l) => l.trim()).map((l) => l.match(/^ */)![0].length));
  return (
    lines
      .map((l) => l.slice(Number.isFinite(min) ? min : 0).trimEnd())
      .join("\n")
      .replace(/\n{3,}/g, "\n\n") + "\n"
  );
}

export function hashStr(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

export function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function languageForPath(path: string): CodeLanguage {
  const ext = path.split(".").pop()?.toLowerCase();
  switch (ext) {
    case "java":
      return "java";
    case "psc":
      return "papyrus";
    case "cs":
      return "csharp";
    case "lua":
      return "lua";
    case "glsl":
    case "fsh":
    case "vsh":
    case "fx":
      return "glsl";
    case "json":
      return "json";
    case "md":
      return "markdown";
    case "xml":
      return "xml";
    case "toml":
    case "properties":
    case "txt":
      return ext === "txt" ? "text" : "toml";
    default:
      return "text";
  }
}

export const file = (path: string, content: string): ModFile => ({ path, language: languageForPath(path), content });

/* ───────────── identity & numbers ───────────── */

export function identity(modName: string) {
  const words = modName.replace(/[^A-Za-z0-9 ]+/g, " ").split(/\s+/).filter(Boolean);
  let cls = words.map((w) => w[0].toUpperCase() + w.slice(1)).join("");
  if (!cls) cls = "AstralMod";
  if (/^\d/.test(cls)) cls = `Cy${cls}`;
  const snake = words.join("_").toLowerCase() || "astral_mod";
  return { cls, snake: /^\d/.test(snake) ? `cy_${snake}` : snake, kebab: snake.replace(/_/g, "-") };
}

export function numbers(input: TemplateInput) {
  const rnd = mulberry32(hashStr(`${input.game.id}|${input.category.key}|${input.modName}|${input.version}`));
  const r = (a: number, b: number, d = 1) => Number((a + rnd() * (b - a)).toFixed(d));
  const i = (a: number, b: number) => Math.round(a + rnd() * (b - a));
  return {
    power: r(5, 14),
    cooldown: r(1.5, 8),
    radius: i(3, 9),
    duration: i(4, 12),
    chance: r(0.12, 0.4, 2),
    health: i(18, 90) * 10,
    speed: r(0.24, 0.42, 2),
    interval: i(2, 10),
    xp: i(12, 80),
    hue: i(0, 359),
    intensity: r(0.6, 1.4, 2),
    rnd,
  };
}

/* ───────────── intent: effects parsed from the prompt ───────────── */

