/**
 * Palworld server settings presets (PURE, client-safe). A "server settings" mod is a set of changes to
 * the `OptionSettings=(...)` line of `PalWorldSettings.ini` (Pal/Saved/Config/<Windows|Linux>Server/).
 * It works on every dedicated server, Linux included, and players install nothing.
 *
 * Keys and defaults: Pocketpair's server guide (docs.palworldgame.com, configuration, v1.0.4 page) and
 * the DefaultPalWorldSettings.ini shipped with the game (mirrored in localcc/PalworldModdingKit).
 * Ranges are Cyrus's own safety bounds unless `official` is set; Pocketpair documents only a few limits.
 *
 * Important: a partial OptionSettings line is NOT a patch. Keys left out fall back to defaults, so a
 * preset is always MERGED into the server's current line (`mergeOptionSettings`), never written raw.
 */

export type SettingKind = "rate" | "int" | "float" | "bool" | "enum";

export type SettingSpec = {
  key: string;
  kind: SettingKind;
  label: string;
  default: number | boolean | string;
  min?: number;
  max?: number;
  /** min/max come from Pocketpair's docs rather than Cyrus's own bounds. */
  official?: boolean;
  options?: string[];
  group: "balance" | "world" | "rules" | "base" | "performance" | "admin";
  /** Raises server load when pushed up. */
  heavy?: boolean;
  /** Can permanently destroy progress (needs explicit confirmation). */
  destructive?: boolean;
  /** Above this, warn (still allowed up to max). */
  warnAbove?: number;
};

const rate = (key: string, label: string, group: SettingSpec["group"], extra: Partial<SettingSpec> = {}): SettingSpec => ({
  key, label, group, kind: "rate", default: 1, min: 0.1, max: 10, warnAbove: 5, ...extra,
});
const flag = (key: string, label: string, def: boolean, group: SettingSpec["group"], extra: Partial<SettingSpec> = {}): SettingSpec => ({
  key, label, group, kind: "bool", default: def, ...extra,
});

/** Keys a Cyrus preset may change. Anything else in a preset is rejected. */
