  flag("bBuildAreaLimit", "No building near fast-travel points", false, "admin"),
  flag("bAllowEnhanceStat_Health", "Allow HP stat points", true, "rules"),
  flag("bAllowEnhanceStat_Attack", "Allow Attack stat points", true, "rules"),
  flag("bAllowEnhanceStat_Stamina", "Allow Stamina stat points", true, "rules"),
