  flag("bAllowGlobalPalboxExport", "Save to Global Palbox", true, "admin"),
  flag("bAllowGlobalPalboxImport", "Load from Global Palbox", false, "admin"),
  flag("bAutoResetGuildNoOnlinePlayers", "Delete inactive guilds' bases", false, "admin", { destructive: true }),
