export const SETTING_BY_KEY: Record<string, SettingSpec> = Object.fromEntries(PALWORLD_SETTINGS.map((s) => [s.key, s]));

/**
 * Keys a preset may never touch: credentials, networking, identity and anything Nxeon's panel owns
 * (ports, player cap from the plan, RCON/REST used by the panel itself).
 */
export const BLOCKED_SETTINGS = new Set([
  "AdminPassword", "ServerPassword", "ServerName", "ServerDescription", "PublicIP", "PublicPort", "Region",
  "RCONEnabled", "RCONPort", "RESTAPIEnabled", "RESTAPIPort", "bUseAuth", "BanListURL", "CrossplayPlatforms",
  "AllowConnectPlatform", "ServerPlayerMaxNum", "CoopPlayerMaxNum", "bIsMultiplay", "LogFormatType", "AutoSaveSpan",
  "bIsUseBackupSaveData", "DenyTechnologyList", "RandomizerSeed",
]);

export type SettingValue = number | boolean | string;
export type SettingsChange = { key: string; value: SettingValue; why?: string };

/* ───────────── format: OptionSettings=(K=V,K="str",K=(a,b)) ───────────── */

/** Formats a value the way the game writes it (floats with 6 decimals, bools True/False). */
export function formatSettingValue(spec: SettingSpec | undefined, value: SettingValue): string {
  if (typeof value === "boolean") return value ? "True" : "False";
  if (typeof value === "number") return spec && spec.kind === "int" ? String(Math.round(value)) : value.toFixed(6);
  if (spec?.kind === "enum") return value;
  return `"${String(value).replace(/"/g, "")}"`;
}

/** Splits the inside of OptionSettings=(...) at top-level commas (quotes and nested parens respected). */
export function splitOptionSettings(inner: string): [string, string][] {
  const out: [string, string][] = [];
  let depth = 0, quoted = false, start = 0;
  const push = (end: number) => {
    const part = inner.slice(start, end).trim();
    if (!part) return;
    const eq = part.indexOf("=");
    if (eq > 0) out.push([part.slice(0, eq).trim(), part.slice(eq + 1).trim()]);
  };
  for (let i = 0; i < inner.length; i++) {
    const ch = inner[i];
    if (ch === '"') quoted = !quoted;
    else if (!quoted && ch === "(") depth++;
    else if (!quoted && ch === ")") depth--;
    else if (!quoted && depth === 0 && ch === ",") {
      push(i);
      start = i + 1;
    }
  }
  push(inner.length);
  return out;
}

const OPTION_RE = /^(\s*OptionSettings\s*=\s*\()(.*)\)\s*$/m;

/** Reads every key=value of the OptionSettings line (raw strings, as written). */
export function parseOptionSettings(ini: string): Map<string, string> {
  const m = ini.match(OPTION_RE);
  return new Map(m ? splitOptionSettings(m[2]) : []);
}

/**
 * Merges changes into the server's existing PalWorldSettings.ini text and returns the new text.
 * Keys not in `changes` keep their current value; a missing file or line gets the section created.
 * Pure: the caller (install flow) reads and writes the real file, with the server STOPPED.
 */
export function mergeOptionSettings(ini: string, changes: SettingsChange[]): string {
  const current = parseOptionSettings(ini);
  for (const c of changes) current.set(c.key, formatSettingValue(SETTING_BY_KEY[c.key], c.value));
  const line = `OptionSettings=(${[...current].map(([k, v]) => `${k}=${v}`).join(",")})`;
  if (OPTION_RE.test(ini)) return ini.replace(OPTION_RE, line);
  const header = "[/Script/Pal.PalGameWorldSettings]";
  if (ini.includes(header)) return ini.replace(header, `${header}\n${line}`);
  return `${ini.trim() ? `${ini.trimEnd()}\n` : ""}${header}\n${line}\n`;
}

/** The preset as a readable fragment (only the changed keys). Never paste it over a full file. */
export function renderPresetFragment(changes: SettingsChange[]): string {
  return `[/Script/Pal.PalGameWorldSettings]\nOptionSettings=(${changes.map((c) => `${c.key}=${formatSettingValue(SETTING_BY_KEY[c.key], c.value)}`).join(",")})\n`;
}

export type SettingsIssue = { key: string; severity: "error" | "warn"; message: string };

/** Validates a preset against the spec table: unknown/blocked keys, types, ranges, heavy and destructive keys. */
export function validateSettingsChanges(changes: SettingsChange[]): SettingsIssue[] {
  const issues: SettingsIssue[] = [];
  const seen = new Set<string>();
  for (const { key, value } of changes) {
    if (seen.has(key)) issues.push({ key, severity: "error", message: `${key} is set twice.` });
    seen.add(key);
    if (BLOCKED_SETTINGS.has(key)) {
      issues.push({ key, severity: "error", message: `${key} is managed by your server panel and can't be changed by a mod.` });
      continue;
    }
    const spec = SETTING_BY_KEY[key];
    if (!spec) {
      issues.push({ key, severity: "error", message: `${key} is not a Palworld server setting Cyrus knows.` });
      continue;
    }
    if (spec.kind === "bool") {
      if (typeof value !== "boolean") issues.push({ key, severity: "error", message: `${key} must be on or off.` });
    } else if (spec.kind === "enum") {
      if (typeof value !== "string" || !spec.options?.includes(value)) issues.push({ key, severity: "error", message: `${key} must be one of ${spec.options?.join(", ")}.` });
    } else {
      if (typeof value !== "number" || !Number.isFinite(value)) issues.push({ key, severity: "error", message: `${key} must be a number.` });
      else {
        if (spec.kind === "int" && !Number.isInteger(value)) issues.push({ key, severity: "error", message: `${key} must be a whole number.` });
        if ((spec.min != null && value < spec.min) || (spec.max != null && value > spec.max))
          issues.push({ key, severity: "error", message: `${key} must be between ${spec.min} and ${spec.max}${spec.official ? " (Pocketpair's limit)" : ""}.` });
        else if (spec.warnAbove != null && value > spec.warnAbove)
          issues.push({ key, severity: "warn", message: `${key} above ${spec.warnAbove} is unusual${spec.heavy ? " and raises server load" : ""}.` });
      }
    }
    if (spec.heavy && spec.kind !== "bool" && typeof value === "number" && typeof spec.default === "number" && value > spec.default && !issues.some((i) => i.key === key && i.severity === "warn"))
      issues.push({ key, severity: "warn", message: `${spec.label} raises server load; watch performance after applying.` });
    if (spec.destructive && value === true)
      issues.push({ key, severity: "warn", message: `${spec.label} can permanently delete progress. Confirm before applying.` });
  }
  return issues;
}

/* ───────────── intent: plain words -> settings changes (zero API cost) ───────────── */

const WORD_MULT: Record<string, number> = { double: 2, twice: 2, triple: 3, quadruple: 4, half: 0.5, halve: 0.5 };

/** Reads a multiplier near a phrase: "3x xp", "xp x3", "double xp", "xp 2.5", "50% more". */
function multiplierNear(text: string, subject: string, fallback: number): number {
  const s = subject;
  const pats: RegExp[] = [
    new RegExp(`(\\d+(?:\\.\\d+)?)\\s*x\\s*(?:the\\s+)?(?:${s})`),
    new RegExp(`x\\s*(\\d+(?:\\.\\d+)?)\\s*(?:${s})`),
    new RegExp(`(?:${s})\\s*(?:rate\\s*)?(?:x|×|at|to)?\\s*(\\d+(?:\\.\\d+)?)\\s*x?\\b`),
  ];
  for (const re of pats) {
    const m = text.match(re);
    if (m) {
      const n = Number(m[1]);
      if (Number.isFinite(n) && n > 0 && n <= 50) return n;
    }
  }
  const pct = text.match(new RegExp(`(\\d+)\\s*%\\s*(more|less|faster|slower)\\s+(?:${s})`));
  if (pct) return pct[2] === "more" || pct[2] === "faster" ? 1 + Number(pct[1]) / 100 : Math.max(0.1, 1 - Number(pct[1]) / 100);
  for (const [w, n] of Object.entries(WORD_MULT)) if (new RegExp(`\\b${w}\\s+(?:the\\s+)?(?:${s})`).test(text)) return n;
  return fallback;
}

type Rule = { test: RegExp; build: (t: string) => SettingsChange[] };

const RULES: Rule[] = [
  { test: /\b(xp|exp|experience)\b|\bfaster level/, build: (t) => [{ key: "ExpRate", value: multiplierNear(t, "xp|exp|experience", /slower|less/.test(t) ? 0.5 : 2), why: "EXP gain" }] },
  { test: /captur|catch rate|easier to catch/, build: (t) => [{ key: "PalCaptureRate", value: multiplierNear(t, "capture rate|capture|catch rate", 1.5), why: "capture rate" }] },
  { test: /\b(drop rate|more drops|more loot|loot rate)\b/, build: (t) => [{ key: "EnemyDropItemRate", value: multiplierNear(t, "drop rate|drops|loot", 2), why: "enemy drops" }] },
  { test: /\b(gather|gathering|resources|mining|harvest)\b/, build: (t) => [{ key: "CollectionDropRate", value: multiplierNear(t, "gathering|resources|mining|harvest", 2), why: "gathering yield" }] },
  { test: /\b(longer|shorter|faster|slower) (days?|daytime)\b/, build: (t) => [{ key: "DayTimeSpeedRate", value: /longer|slower/.test(t.match(/\b(longer|shorter|faster|slower) (days?|daytime)\b/)![1]) ? 0.5 : 2, why: "day length" }] },
  { test: /\b(longer|shorter|faster|slower) nights?\b/, build: (t) => [{ key: "NightTimeSpeedRate", value: /longer|slower/.test(t.match(/\b(longer|shorter|faster|slower) nights?\b/)![1]) ? 0.5 : 2, why: "night length" }] },
  { test: /\b(work speed|faster work|work faster|faster crafting|craft faster)\b/, build: (t) => [{ key: "WorkSpeedRate", value: multiplierNear(t, "work speed|work|crafting", 2), why: "work speed" }] },
  { test: /\b(hatch|eggs? faster|faster eggs?|incubat)/, build: () => [{ key: "PalEggDefaultHatchingTime", value: 0.25, why: "egg hatch time" }] },
  { test: /\b(less|no|slower) hunger\b|\bhunger (slower|less)\b/, build: () => [{ key: "PlayerStomachDecreaceRate", value: 0.5 }, { key: "PalStomachDecreaceRate", value: 0.5, why: "hunger" }] },
  { test: /\b(carry more|lighter items|item weight|less weight)\b/, build: () => [{ key: "ItemWeightRate", value: 0.5, why: "item weight" }] },
  { test: /\bhardcore\b/, build: () => [{ key: "bHardcore", value: true, why: "hardcore" }] },
  { test: /\b(lose|lost) (my |your |their )?pals\b|\bpal ?lost\b|\bpermadeath\b/, build: () => [{ key: "bPalLost", value: true, why: "pals lost on death" }] },
  { test: /\bpvp\b/, build: () => [{ key: "bIsPvP", value: true }, { key: "bEnablePlayerToPlayerDamage", value: true, why: "PvP" }] },
  { test: /\bno death penalty\b|\bkeep (my |your )?items\b/, build: () => [{ key: "DeathPenalty", value: "None", why: "no death penalty" }] },
  { test: /\b(drop|lose) (everything|all items)\b/, build: () => [{ key: "DeathPenalty", value: "ItemAndEquipment", why: "harsh death penalty" }] },
  { test: /\b(more|bigger) (pals per base|base workers|workers)\b|\bbigger bases?\b/, build: () => [{ key: "BaseCampWorkerMaxNum", value: 25, why: "pals per base" }] },
  { test: /\bmore bases\b/, build: () => [{ key: "BaseCampMaxNumInGuild", value: 6, why: "bases per guild" }] },
  { test: /\bmore (pals|spawns)\b|\bspawn rate\b/, build: (t) => [{ key: "PalSpawnNumRate", value: Math.min(3, multiplierNear(t, "spawn rate|spawns|pals", 1.5)), why: "spawn amount" }] },
  { test: /\bno (raids|invaders|base raids)\b/, build: () => [{ key: "bEnableInvaderEnemy", value: false, why: "raids off" }] },
  { test: /\bno fast travel\b/, build: () => [{ key: "bEnableFastTravel", value: false, why: "fast travel off" }] },
  { test: /\b(tougher|harder|stronger) (pals|enemies|wild pals)\b/, build: () => [{ key: "PalDamageRateAttack", value: 1.5 }, { key: "PalDamageRateDefense", value: 0.75, why: "tougher pals" }] },
  { test: /\b(easier|weaker) (pals|enemies)\b/, build: () => [{ key: "PalDamageRateAttack", value: 0.75 }, { key: "PalDamageRateDefense", value: 1.25, why: "easier pals" }] },
  { test: /\brandomi[sz]er|random spawns\b/, build: () => [{ key: "RandomizerType", value: "Region", why: "randomizer" }] },
  { test: /\b(lighter|less lag|lag|performance|optimi[sz]e)\b/, build: () => [{ key: "DropItemMaxNum", value: 1500 }, { key: "DropItemAliveMaxHours", value: 0.5, why: "lighter server" }] },
];

/** Words that say "this is about server settings", so creative prompts don't get hijacked. */
const SETTINGS_CUE = /\b(server|settings?|rates?|multiplier|x\d|\d+x|double|triple|half|hardcore|pvp|death penalty|rules|preset|lag|performance|randomi[sz]er)\b/;

/** Plain words -> settings changes. Empty when the prompt isn't a settings request. Deterministic. */
export function settingsIntent(prompt: string): SettingsChange[] {
  const t = prompt.toLowerCase();
  if (!SETTINGS_CUE.test(t)) return [];
  const out = new Map<string, SettingsChange>();
  for (const r of RULES) if (r.test.test(t)) for (const c of r.build(t)) if (!out.has(c.key)) out.set(c.key, c);
  // Clamp to the spec so a typo ("xp x500") still yields a valid preset.
  return [...out.values()].map((c) => {
    const spec = SETTING_BY_KEY[c.key];
    if (spec && typeof c.value === "number") {
      let v = c.value;
      if (spec.max != null) v = Math.min(spec.max, v);
      if (spec.min != null) v = Math.max(spec.min, v);
      if (spec.kind === "int") v = Math.round(v);
      return { ...c, value: Number(v.toFixed(3)) };
    }
    return c;
  });
}

