/**
 * Palworld generator · v2 (2026-10-08). Two outputs:
 *
 *  - SERVER SETTINGS presets (`PalWorldSettings.patch.ini` + `Cyrus.json`) for prompts that are really
 *    about server rules (XP rate, day length, hardcore...). Works on every dedicated server, Linux too.
 *  - UE4SS Lua mods packaged for Palworld's OFFICIAL mod loader: `Info.json` at the package root,
 *    `Scripts/main.lua` wiring hooks, `Scripts/<snake>/<module>.lua` the archetype logic and
 *    `Scripts/<snake>/effects.lua` the shared, guarded game accessors. `Cyrus.json` records which side
 *    the mod runs on (server / both / host / client) so the studio and install flow never guess.
 *
 * Every game name used below was checked against Palworld's published headers (localcc/PalworldModdingKit,
 * Source/Pal/Public, the 1.0 kit) or the UE4SS Lua API docs; engine names are standard UE5.1 reflected
 * functions. Nothing is tagged "plausible" any more: names we could not verify were replaced or removed.
 * Data-table asset names and row ids are looked up at runtime and logged when missing (see GameSupport.unknowns).
 */
import type { ModFile } from "@/lib/cyrus/types";
import support, { PALWORLD_CURRENT_VERSION, PALWORLD_KINDS, PALWORLD_MIN_REVISION, PALWORLD_UE4SS_PACKAGE, type PalworldModKind } from "@/lib/cyrus/games/palworld";
import { renderPresetFragment, settingsIntent, SETTING_BY_KEY, validateSettingsChanges, type SettingsChange } from "@/lib/cyrus/games/palworld.settings";
import { ARCH, code, effectsFor, file, hashStr, identity, MODEL_NAME, numbers, sub, type Built, type EffectKey, type TemplateInput } from "../kit";

type N = ReturnType<typeof numbers>;
/** [config key, Lua literal, comment] */
type Def = [string, string, string];

export const PALWORLD_GENERATOR = "cyrus-palworld/2";

/* ───────────── effects → Palworld ───────────── */

/**
 * `hit` runs after a hit lands (TARGET was hit by SOURCE, `damage` = HP actually lost); `pulse` runs anywhere.
 * Status ids are EPalStatusID names (Burn, Freeze, Electrical, Poison, Stun), read from the enum at runtime.
 */
const FX: Record<EffectKey, { hit: string; pulse: string; needs: string[] }> = {
  frost: { hit: 'Fx.status(TARGET, "Freeze")', pulse: 'Fx.status(TARGET, "Freeze")', needs: ["status"] },
  fire: { hit: 'Fx.status(TARGET, "Burn")', pulse: 'Fx.status(TARGET, "Burn")', needs: ["status"] },
  storm: { hit: 'Fx.status(TARGET, "Electrical")', pulse: 'Fx.status(TARGET, "Electrical")', needs: ["status"] },
  blink: { hit: "Fx.blink(SOURCE, 150, TARGET)", pulse: "Fx.blink(SOURCE, Config.blinkDistance)", needs: ["blink"] },
  heal: { hit: "Fx.heal(SOURCE, Config.power * 4)", pulse: "Fx.heal(SOURCE, Config.power * 10)", needs: ["heal"] },
  poison: { hit: 'Fx.status(TARGET, "Poison")', pulse: 'Fx.status(TARGET, "Poison")', needs: ["status"] },
  // Palworld has no safe way to spawn a pal from Lua (a bare actor has no individual parameter and can
  // leave broken pals in a save), so "summon" staggers the target instead of spawning anything.
  summon: { hit: 'if math.random() < Config.staggerChance then Fx.status(TARGET, "Stun") end', pulse: 'if math.random() < Config.staggerChance then Fx.status(TARGET, "Stun") end', needs: ["status"] },
  flight: { hit: "Fx.launch(SOURCE, Config.jumpMultiplier)", pulse: "Fx.launch(SOURCE, Config.jumpMultiplier)", needs: ["launch"] },
  void: { hit: "Fx.drain(TARGET, SOURCE, Config.power * 3)", pulse: "Fx.drain(TARGET, SOURCE, Config.power * 3)", needs: ["heal"] },
  lunar: { hit: "if Fx.isNight() then Fx.damage(TARGET, damage * (Config.nightMultiplier - 1)) end", pulse: "if Fx.isNight() then Fx.heal(SOURCE, Config.power * 5) end", needs: ["time", "heal"] },
  auto: { hit: "Fx.workSpeed(SOURCE, Config.workSpeedMultiplier)", pulse: "Fx.workSpeed(TARGET, Config.workSpeedMultiplier)", needs: ["work"] },
  neon: { hit: 'Fx.toast(Fx.text("hit", "%s  -%d", Fx.palName(TARGET), damage))', pulse: 'Fx.toast(Fx.text("pulse", "%s ▸ surge", Fx.palName(TARGET)))', needs: [] },
};

function fxDefs(keys: EffectKey[], n: N): Def[] {
  const has = (...k: EffectKey[]) => k.some((x) => keys.includes(x));
  const out: Def[] = [];
  if (has("heal", "void", "lunar")) out.push(["power", String(n.power), "base heal / drain per proc (HP)"]);
  if (has("blink")) out.push(["blinkDistance", String(n.radius * 100), "blink distance (cm)"]);
  if (has("summon")) out.push(["staggerChance", String(n.chance), "chance per proc to stun the target"]);
  if (has("flight")) out.push(["jumpMultiplier", (1.6 + n.speed * 2).toFixed(2), "JumpZVelocity multiplier while launched"]);
  if (has("lunar")) out.push(["nightMultiplier", (1 + n.intensity / 2).toFixed(2), "damage multiplier between dusk and dawn"]);
  if (has("auto")) out.push(["workSpeedMultiplier", (1 + n.speed * 2).toFixed(2), "CraftSpeed multiplier for touched pals"]);
  return out;
}

/* ───────────── Palworld data ───────────── */

/** [match, DT_PalMonsterParameter row, display name]. Row ids are looked up at runtime and logged if missing. */
const PALS: [RegExp, string, string][] = [
  [/ice fox|frost fox|snow fox|foxcicle/, "IceFox", "Foxcicle"],
  [/fox|kitsune|foxpark/, "Kitsunebi", "Foxparks"],
  [/cat|kitten|cattiva/, "PinkCat", "Cattiva"],
  [/lamb|sheep|wool/, "SheepBall", "Lamball"],
  [/chick|chicken|egg/, "ChickenPal", "Chikipi"],
  [/penguin|penking/, "Penguin", "Pengullet"],
  [/wolf|hound|direhowl/, "Garm", "Direhowl"],
  [/panda|bear|grizz/, "ElecPanda", "Grizzbolt"],
  [/horse|stallion|steed/, "IceHorse", "Frostallion"],
  [/griffin|griffon|raven|crow/, "BlackGriffon", "Shadowbeak"],
  [/jet|dragon|wyvern|drake/, "JetDragon", "Jetragon"],
  [/anubis|jackal/, "Anubis", "Anubis"],
  [/mammoth|elephant/, "GrassMammoth", "Mammorest"],
];
const BY_EFFECT: Partial<Record<EffectKey, [string, string]>> = {
  frost: ["IceFox", "Foxcicle"],
  fire: ["Kitsunebi", "Foxparks"],
  storm: ["ElecPanda", "Grizzbolt"],
  void: ["BlackGriffon", "Shadowbeak"],
  flight: ["JetDragon", "Jetragon"],
  poison: ["Garm", "Direhowl"],
};

function pickPal(input: TemplateInput, fx: EffectKey[]): { id: string; label: string } {
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  const hit = PALS.find(([re]) => re.test(text));
  if (hit) return { id: hit[1], label: hit[2] };
  const byFx = fx.map((k) => BY_EFFECT[k]).find(Boolean);
  if (byFx) return { id: byFx[0], label: byFx[1] };
  const [, id, label] = PALS[hashStr(input.modName) % PALS.length];
  return { id, label };
}

/** DT_ItemDataTable rows; swap for the weapon you're retuning. */
function pickWeapon(text: string): string {
  if (/bow|arrow/.test(text)) return "Bow";
  if (/shotgun/.test(text)) return "PumpActionShotgun";
  if (/pistol|handgun|revolver/.test(text)) return "HandGun_Default";
  if (/spear|glaive|lance/.test(text)) return "Spear";
  if (/rocket|launcher/.test(text)) return "RocketLauncher_Default";
  return "AssaultRifle_Default1";
}

const LOOT = ["Wood", "Stone", "Fiber", "Leather", "Bone", "Wool", "PalSphere", "PalSphere_Mega", "Money"];

const lit = (v: string | number | boolean) => (typeof v === "string" ? JSON.stringify(v) : String(v));

/* ───────────── effects.lua (shared, guarded helpers) ───────────── */

function effectsModule(input: TemplateInput, snake: string, cls: string, needs: Set<string>): string {
  const need = (k: string) => needs.has(k);
  return code`
    --[[
        ${input.modName} · effects.lua
        Shared helpers every module goes through. Game names were checked against Palworld ${PALWORLD_CURRENT_VERSION}'s
        published headers; every game call is wrapped so a name that changes in a patch logs a warning
        instead of crashing. Anything that changes game state only runs where the game is authoritative
        (single-player, the co-op host, or the dedicated server).
    ]]
    local UEHelpers = require("UEHelpers")

    local M = {}
    local MOD = "[${cls}]"
    local Config = {}

    function M.log(fmt, ...)
        print(string.format("%s " .. fmt .. "\\n", MOD, ...))
    end

    --- Merges Scripts/${snake}/config.lua (optional) over the module defaults.
    function M.loadConfig(defaults)
        local cfg = {}
        for k, v in pairs(defaults) do cfg[k] = v end
        local ok, user = pcall(require, "${snake}.config")
        if ok and type(user) == "table" then
            for k, v in pairs(user) do cfg[k] = v end
        elseif not ok then
            M.log("no config.lua, using defaults")
        end
        Config = cfg
        return cfg
    end

    local strings
    --- Looks the key up in lang/<language>.lua; the English fallback keeps the mod usable without it.
    function M.text(key, fallback, ...)
        if strings == nil then
            local ok, t = pcall(require, "${snake}.lang." .. (Config.language or "en"))
            strings = ok and t or false
        end
        return string.format((strings and strings[key]) or fallback, ...)
    end

    function M.valid(obj)
        return obj ~= nil and obj:IsValid()
    end

    --- Calls fn and logs (once per label) instead of erroring when a game name moved in a patch.
    local warned = {}
    function M.try(label, fn)
        local ok, result = pcall(fn)
        if ok then return result end
        if not warned[label] then
            warned[label] = true
            M.log("%s unavailable in this game version: %s", label, tostring(result))
        end
        return nil
    end

    function M.world()
        return UEHelpers.GetWorld()
    end

    local Kismet
    --- Engine UKismetSystemLibrary::IsServer: true in single-player, for the co-op host and on a dedicated server.
    function M.isServer()
        Kismet = Kismet or UEHelpers.GetKismetSystemLibrary()
        return M.try("IsServer", function() return Kismet:IsServer(M.world()) end) == true
    end

    function M.isDedicated()
        Kismet = Kismet or UEHelpers.GetKismetSystemLibrary()
        return M.try("IsDedicatedServer", function() return Kismet:IsDedicatedServer(M.world()) end) == true
    end

    --- The player on this PC (single-player, host or client). Nil on a dedicated server, which has none.
    function M.player()
        if M.isDedicated() then return nil end
        local controller = UEHelpers.GetPlayerController()
        local pawn = M.valid(controller) and controller.Pawn
        return M.valid(pawn) and pawn or nil
    end

    --- Every connected player character (all of them on a server, the visible ones on a client).
    function M.players()
        local out = {}
        for _, p in ipairs(FindAllOf("PalPlayerCharacter") or {}) do
            if p:IsValid() then out[#out + 1] = p end
        end
        return out
    end

    local PlayerClass
    function M.isPlayer(actor)
        PlayerClass = PlayerClass or StaticFindObject("/Script/Pal.PalPlayerCharacter")
        return M.valid(actor) and M.valid(PlayerClass) and actor:IsA(PlayerClass)
    end

    --- APalCharacter.CharacterParameterComponent (HP, level, otomo flag, work).
    function M.comp(actor)
        local comp = M.valid(actor) and actor.CharacterParameterComponent
        return M.valid(comp) and comp or nil
    end

    --- UPalIndividualCharacterParameter behind a PalCharacter (SaveParameter: talents, owner, passives).
    function M.param(actor)
        local comp = M.comp(actor)
        if not comp then return nil end
        local param = comp:GetIndividualParameter()
        return M.valid(param) and param or nil
    end

    function M.palId(actor)
        local param = M.param(actor)
        return param and param.SaveParameter.CharacterID:ToString() or "?"
    end

    function M.palName(actor)
        local param = M.param(actor)
        if not param then return "?" end
        local nick = param.SaveParameter.NickName:ToString()
        return nick ~= "" and nick or param.SaveParameter.CharacterID:ToString()
    end

    --- Wild pals have an empty OwnerPlayerUId; party, palbox and base pals carry their owner's GUID.
    function M.isOwned(param)
        local uid = param.SaveParameter.OwnerPlayerUId
        return uid.A ~= 0 or uid.B ~= 0 or uid.C ~= 0 or uid.D ~= 0
    end

    function M.distance(a, b)
        local p, q = a:K2_GetActorLocation(), b:K2_GetActorLocation()
        local dx, dy, dz = p.X - q.X, p.Y - q.Y, p.Z - q.Z
        return math.sqrt(dx * dx + dy * dy + dz * dz)
    end

    --- Non-player PalCharacters within radius (cm) of origin.
    function M.palsNear(origin, radius)
        local out = {}
        for _, pal in ipairs(FindAllOf("PalCharacter") or {}) do
            if pal:IsValid() and not M.isPlayer(pal) and M.distance(origin, pal) <= radius then
                out[#out + 1] = pal
            end
        end
        return out
    end

    --- World time in seconds (pauses with the game, unlike os.clock()).
    function M.now()
        return UEHelpers.GetGameplayStatics():GetTimeSeconds(M.world())
    end

    local PalUtility
    function M.util()
        PalUtility = PalUtility or StaticFindObject("/Script/Pal.Default__PalUtility")
        return M.valid(PalUtility) and PalUtility or nil
    end

    --- In-game notice (UPalUtility::SendSystemAnnounce, a server broadcast) mirrored to the UE4SS log.
    function M.toast(text)
        M.log("%s", text)
        local util = M.util()
        if util and M.isServer() then
            M.try("SendSystemAnnounce", function() util:SendSystemAnnounce(M.world(), text) end)
        end
    end

    local tables = {}
    --- A DataTable found by its short name (no hard-coded asset path), cached per world.
    function M.table(name)
        local dt = tables[name]
        if not M.valid(dt) then
            dt = FindObject("DataTable", name)
            if not M.valid(dt) then dt = FindObject(nil, name) end
            tables[name] = dt
        end
        if not M.valid(dt) then
            M.log("data table %s not found", name)
            return nil
        end
        return dt
    end

    --- UDataTable:FindRow returns a live reference: writes apply to the table immediately.
    function M.row(tableName, rowName)
        local dt = M.table(tableName)
        if not dt then return nil end
        local row = M.try(tableName .. ":FindRow", function() return dt:FindRow(rowName) end)
        if not row then M.log("row %s missing from %s", rowName, tableName) end
        return row
    end

    function M.eachRow(tableName, fn)
        local dt = M.table(tableName)
        if dt then M.try(tableName .. ":ForEachRow", function() dt:ForEachRow(fn) end) end
    end
    ${need("status") && enumBlock()}
    ${need("status") && code`

      --- Adds an EPalStatusID status (Burn, Freeze, Electrical, Poison, Stun) via UPalStatusComponent::AddStatus.
      function M.status(target, kind)
          local id = statusIds()[kind]
          local status = M.valid(target) and target.StatusComponent
          if id == nil or not M.valid(status) or not M.isServer() then return end
          M.try("AddStatus", function() status:AddStatus(id) end)
      end`}
    ${need("heal") && code`

      -- HP lives on UPalCharacterParameterComponent as an FFixedPoint64: Value = HP × 1000.
      function M.heal(actor, amount)
          local comp = M.comp(actor)
          if not comp or not M.isServer() then return end
          local hp, max = comp:GetHP().Value, comp:GetMaxHP().Value
          comp:SetHP({ Value = math.min(max, hp + math.floor(amount * 1000)) })
      end

      --- SetHP never kills: the target is left on 1 HP for the next real hit. Returns HP removed.
      function M.damage(actor, amount)
          local comp = M.comp(actor)
          if not comp or not M.isServer() or amount <= 0 then return 0 end
          local hp = comp:GetHP().Value
          local nextHp = math.max(1000, hp - math.floor(amount * 1000))
          comp:SetHP({ Value = nextHp })
          return (hp - nextHp) / 1000
      end

      function M.drain(target, source, amount)
          M.heal(source, M.damage(target, amount))
      end`}
    ${need("blink") && code`

      --- Teleports along the facing direction, or next to \`toward\` when given.
      function M.blink(actor, distance, toward)
          if not M.valid(actor) or not M.isServer() then return end
          local from = actor:K2_GetActorLocation()
          local to
          if toward then
              local t = toward:K2_GetActorLocation()
              local dx, dy = from.X - t.X, from.Y - t.Y
              local len = math.max(1, math.sqrt(dx * dx + dy * dy))
              to = { X = t.X + dx / len * distance, Y = t.Y + dy / len * distance, Z = t.Z + 20 }
          else
              local dir = actor:GetActorForwardVector()
              to = { X = from.X + dir.X * distance, Y = from.Y + dir.Y * distance, Z = from.Z + 50 }
          end
          actor:K2_SetActorLocation(to, false, {}, true)
      end`}
    ${need("launch") && code`

      --- Temporarily raises CharacterMovement.JumpZVelocity and jumps (movement is predicted on the
      --- player's PC, so this belongs in single-player / host mods).
      function M.launch(actor, multiplier)
          local move = M.valid(actor) and actor.CharacterMovement
          if not M.valid(move) then return end
          local base = move.JumpZVelocity
          move.JumpZVelocity = base * multiplier
          actor:Jump()
          ExecuteWithDelay(450, function()
              ExecuteInGameThread(function()
                  if move:IsValid() then move.JumpZVelocity = base end
              end)
          end)
      end`}
    ${need("time") && code`

      --- Hour of the in-game day (0-23): UPalUtility::GetTimeManager → UPalTimeManager::GetCurrentPalWorldTime_Hour.
      function M.hour()
          local util = M.util()
          if not util then return 12 end
          return M.try("GetCurrentPalWorldTime_Hour", function() return util:GetTimeManager(M.world()):GetCurrentPalWorldTime_Hour() end) or 12
      end

      --- UPalUtility::IsNight, falling back to the clock.
      function M.isNight()
          local util = M.util()
          local night = util and M.try("IsNight", function() return util:IsNight(M.world()) end)
          if type(night) == "boolean" then return night end
          local h = M.hour()
          return h >= 19 or h < 5
      end`}
    ${need("work") && code`

      local baseSpeed = {}
      --- Scales SaveParameter.CraftSpeed (work speed) from its original value, so repeats never stack.
      function M.workSpeed(pal, multiplier)
          local param = M.param(pal)
          if not param or not M.isServer() then return end
          local key = pal:GetAddress()
          baseSpeed[key] = baseSpeed[key] or param.SaveParameter.CraftSpeed
          param.SaveParameter.CraftSpeed = math.floor(baseSpeed[key] * multiplier)
      end`}
    ${need("give") && code`

      --- APawn.PlayerState → APalPlayerState::GetInventoryData → UPalPlayerInventoryData::AddItem_ServerInternal
      --- (FName StaticItemId, int32 Count, bool IsAssignPassive, float LogDelay, bool bNotifyLog). Server only.
      function M.give(player, itemId, count)
          if not M.valid(player) or not M.isServer() then return false end
          local state = player.PlayerState
          if not M.valid(state) then return false end
          local inventory = state:GetInventoryData()
          if not M.valid(inventory) then return false end
          return M.try("AddItem_ServerInternal", function()
              inventory:AddItem_ServerInternal(FName(itemId), count, false, 0.0, true)
              return true
          end) == true
      end`}
    ${need("camp") && code`

      --- True when the actor stands inside any base camp's work area (UPalBaseCampModel Transform + AreaRange).
      function M.inCamp(actor, padding)
          local p = actor:K2_GetActorLocation()
          for _, camp in ipairs(FindAllOf("PalBaseCampModel") or {}) do
              if camp:IsValid() then
                  local c, r = camp.Transform.Translation, camp.AreaRange + (padding or 0)
                  local dx, dy = p.X - c.X, p.Y - c.Y
                  if dx * dx + dy * dy <= r * r then return true end
              end
          end
          return false
      end`}
    ${need("persist") && code`

      -- Saves live next to the mod (…/UE4SS/Mods/<Package>/), resolved from this file's own path.
      -- Only file names (no folders, no "..") are accepted, so a mod can never write outside its folder.
      local source = debug.getinfo(1, "S").source:gsub("^@", "")
      local MOD_DIR = source:match("^(.*[/\\\\])[Ss]cripts[/\\\\]") or ""

      local function safeName(name)
          return type(name) == "string" and name:match("^[%w_%-]+%.lua$") ~= nil
      end

      function M.serialize(value, indent)
          indent = indent or ""
          if type(value) ~= "table" then
              return type(value) == "string" and string.format("%q", value) or tostring(value)
          end
          local keys = {}
          for k in pairs(value) do keys[#keys + 1] = k end
          table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
          local lines = { "{" }
          for _, k in ipairs(keys) do
              local key = type(k) == "number" and ("[" .. k .. "]") or string.format("[%q]", k)
              lines[#lines + 1] = string.format("%s    %s = %s,", indent, key, M.serialize(value[k], indent .. "    "))
          end
          lines[#lines + 1] = indent .. "}"
          return table.concat(lines, "\\n")
      end

      function M.save(name, data)
          if not safeName(name) or MOD_DIR == "" then return false end
          local f = io.open(MOD_DIR .. name, "w")
          if not f then return false end
          f:write("return ", M.serialize(data), "\\n")
          f:close()
          return true
      end

      --- Loads a saved table in an empty environment so a hand-edited file can't run code.
      function M.load(name)
          if not safeName(name) or MOD_DIR == "" then return nil end
          local chunk = loadfile(MOD_DIR .. name, "t", {})
          if not chunk then return nil end
          local ok, data = pcall(chunk)
          return ok and type(data) == "table" and data or nil
      end`}

    return M`;
}

function enumBlock() {
  return code`

    --- Reads a UEnum into { ShortName = value } so we never hard-code indices that shift between patches.
    --- (Reading enums needs the Palworld build of UE4SS; the stock release crashes here since 0.4.1.5.)
    local function enumValues(path)
        local values = {}
        local enum = StaticFindObject(path)
        if M.valid(enum) then
            enum:ForEachName(function(name, value)
                local full = name:ToString()
                values[full:match("::(.+)$") or full] = value
            end)
        end
        return values
    end

    local StatusIds
    local function statusIds()
        StatusIds = StatusIds or enumValues("/Script/Pal.EPalStatusID")
        return StatusIds
    end`;
}

/* ───────────── archetype modules ───────────── */

interface Ctx {
  input: TemplateInput;
  n: N;
  cls: string;
  snake: string;
  fx: EffectKey[];
  pal: { id: string; label: string };
  text: string;
}

interface Mode {
  /** Module file under Scripts/<snake>/ and its local name in main.lua. */
  file: string;
  local: string;
  summary: string;
  /** Where it must be installed; drives Info.json's IsServer rule and the customer label. */
  kind: Exclude<PalworldModKind, "server-settings">;
  /** Changes that stay in the world save after the mod is removed. */
  persists?: string;
  /** Needs files Cyrus cannot produce (e.g. an audio soundbank); shown as a template preview. */
  preview?: string;
  needs: string[];
  ue?: boolean;
  /** False when the module doesn't run effect snippets (overlay, audio, post-process). */
  fx?: boolean;
  defs: Def[];
  body: string;
  /** Registered once, after the first world is ready (UFunction hooks need their class loaded). */
  hooks: string;
  /** Registered at load (key binds, NotifyOnNewObject, loops: none need the class to exist yet). */
  early?: string;
  strings: Record<string, string>;
  spec: string;
}

const hit = (c: Ctx, target: string, source: string) => c.fx.map((k) => sub(FX[k].hit, target, source));
const pulse = (c: Ctx, target: string, source: string) => c.fx.map((k) => sub(FX[k].pulse, target, source));
const COOLDOWN = { cooldown: "Recharging · %.1fs" };

/**
 * After a hit is processed. UPalDamageReactionComponent::CallOnActualDamageProcessed_ToAll(Attacker, Defender,
 * ActualDamage) is a NetMulticast UFunction, so it runs on the server and on clients; modules only act on the server.
 */
function damageHook(local: string) {
  return code`
    RegisterHook("/Script/Pal.PalDamageReactionComponent:CallOnActualDamageProcessed_ToAll", function(self, attacker, defender, damage)
        ${local}.onDamage(attacker:get(), defender:get(), damage:get())
    end)`;
}

const keyBind = (key: string, call: string, ctrl = false) => code`
  RegisterKeyBind(Key[Config.${key}], ${ctrl ? "{ ModifierKey.CONTROL }, " : ""}function()
      ExecuteInGameThread(${call.endsWith("()") ? call.slice(0, -2) : `function() ${call} end`})
  end)`;

const loop = (seconds: string, call: string) => code`
  LoopAsync(math.floor(${seconds} * 1000), function()
      ExecuteInGameThread(${call})
      return false -- keep looping
  end)`;

function weaponMode(c: Ctx): Mode {
  const { n } = c;
  return {
    file: "weapon",
    local: "Weapon",
    kind: "server-lua",
    summary: "Retunes the weapon's DT_ItemDataTable row and adds crit / charged bonus damage after each hit.",
    needs: ["heal"],
    defs: [
      ["itemId", lit(pickWeapon(c.text)), "DT_ItemDataTable row this mod retunes"],
      ["attackBonus", String(Math.round(n.power * 3)), "flat PhysicalAttackValue added to the row"],
      ["critChance", String(n.chance), "chance per hit to crit"],
      ["critMultiplier", (1.5 + n.intensity / 2).toFixed(2), "damage multiplier on a crit"],
      ["chargeMultiplier", (1.4 + n.power / 10).toFixed(2), "multiplier for the first hit after charging (single-player / host)"],
      ["cooldown", String(n.cooldown), "seconds between charges"],
      ["abilityKey", lit("F7"), "UE4SS Key name that charges the next shot"],
    ],
    body: code`
      local state = { charged = false, readyAt = 0, baseAttack = nil }

      function M.onWorldReady()
          local row = Fx.row("DT_ItemDataTable", Config.itemId)
          if not row then return end
          state.baseAttack = state.baseAttack or row.PhysicalAttackValue
          row.PhysicalAttackValue = state.baseAttack + Config.attackBonus
          Fx.log("%s attack %d -> %d", Config.itemId, state.baseAttack, row.PhysicalAttackValue)
      end

      --- APalPlayerCharacter.ShooterComponent:GetHasWeapon() → APalWeaponBase:GetItemId().StaticId
      local function heldItem(actor)
          local shooter = actor.ShooterComponent
          if not Fx.valid(shooter) then return nil end
          local weapon = shooter:GetHasWeapon()
          return Fx.valid(weapon) and weapon:GetItemId().StaticId:ToString() or nil
      end

      function M.rollCrit(roll, chance)
          return roll < chance
      end

      --- Extra HP to remove on top of the hit that already landed.
      function M.bonus(damage, charged, crit)
          local m = (charged and Config.chargeMultiplier or 1) * (crit and Config.critMultiplier or 1)
          return math.floor(damage * (m - 1) + 0.5)
      end

      function M.charge(now)
          if now < state.readyAt then
              return Fx.toast(Fx.text("cooldown", "Recharging · %.1fs", state.readyAt - now))
          end
          state.charged, state.readyAt = true, now + Config.cooldown
          Fx.log("%s", Fx.text("charged", "%s charged", "${c.input.modName}"))
      end

      function M.onDamage(attacker, target, damage)
          if not Fx.isServer() or not Fx.valid(target) or not Fx.isPlayer(attacker) then return end
          if Fx.try("held weapon", function() return heldItem(attacker) end) ~= Config.itemId then return end
          Fx.damage(target, M.bonus(damage, state.charged, M.rollCrit(math.random(), Config.critChance)))
          state.charged = false
          ${hit(c, "target", "attacker")}
      end`,
    hooks: damageHook("Weapon"),
    early: keyBind("abilityKey", "Weapon.charge(Fx.now())"),
    strings: { ...COOLDOWN, charged: "%s charged" },
    spec: code`
      it("crits only under the chance", function()
          assert.is_true(M.rollCrit(0.01, Config.critChance))
          assert.is_false(M.rollCrit(0.99, Config.critChance))
      end)

      it("adds no bonus on a plain hit and stacks charge with crit", function()
          assert.are.equal(0, M.bonus(100, false, false))
          assert.are.equal(math.floor(100 * (Config.chargeMultiplier * Config.critMultiplier - 1) + 0.5), M.bonus(100, true, true))
      end)`,
  };
}

function spellMode(c: Ctx): Mode {
  const { n } = c;
  return {
    file: "spell",
    local: "Spell",
    kind: "host-lua",
    summary: "A keybound area spell that scales with distance and skips your own pals.",
    needs: ["heal"],
    defs: [
      ["radius", String(n.radius * 100), "spell radius (cm)"],
      ["spellDamage", String(Math.round(n.power * 5)), "damage at the centre (HP)"],
      ["cooldown", String(n.cooldown), "recast time (seconds)"],
      ["castKey", lit("F7"), "UE4SS Key name that casts"],
    ],
    body: code`
      local readyAt = 0

      --- Damage falls off linearly to 35% at the edge of the radius.
      function M.falloff(distance, radius)
          if distance > radius then return 0 end
          return 1 - 0.65 * (distance / radius)
      end

      function M.onWorldReady()
          readyAt = 0
      end

      function M.cast(now)
          local caster = Fx.player()
          if not caster or not Fx.isServer() then return end
          if now < readyAt then
              return Fx.toast(Fx.text("cooldown", "Recharging · %.1fs", readyAt - now))
          end
          readyAt = now + Config.cooldown
          local hits = 0
          for _, target in ipairs(Fx.palsNear(caster, Config.radius)) do
              local param = Fx.param(target)
              if param and not Fx.isOwned(param) then
                  local damage = Fx.damage(target, Config.spellDamage * M.falloff(Fx.distance(caster, target), Config.radius))
                  ${hit(c, "target", "caster")}
                  hits = hits + 1
              end
          end
          Fx.toast(Fx.text("cast", "%s · %d hit", "${c.input.modName}", hits))
      end`,
    hooks: "",
    early: keyBind("castKey", "Spell.cast(Fx.now())"),
    strings: { ...COOLDOWN, cast: "%s · %d hit" },
    spec: code`
      it("falls off toward the edge", function()
          assert.are.equal(1, M.falloff(0, 1000))
          assert.is_true(M.falloff(900, 1000) < M.falloff(100, 1000))
          assert.are.equal(0, M.falloff(1200, 1000))
      end)`,
  };
}

function itemMode(c: Ctx): Mode {
  const { n } = c;
  const loot = LOOT.filter((_, i) => (hashStr(c.cls) >> i) & 1).slice(0, 4);
  const entries = (loot.length >= 2 ? loot : ["Wood", "PalSphere", "Money"]).map(
    (id, i) => `{ id = "${id}", weight = ${40 - i * 8}, min = ${id === "Money" ? 50 : 2}, max = ${id === "Money" ? 200 : 6 + i * 2} },`,
  );
  return {
    file: "item",
    local: "Item",
    kind: "host-lua",
    persists: "Items it hands out stay in your inventory and world save after the mod is removed.",
    summary: "A keybound satchel that rolls weighted loot into the player's inventory.",
    needs: ["give"],
    defs: [
      ["lootTable", `{\n${entries.map((e) => `    ${e}`).join("\n")}\n}`, "weighted DT_ItemDataTable rows"],
      ["rolls", String(2 + (n.radius % 3)), "items granted per use"],
      ["maxStack", String(n.health > 500 ? 9999 : 999), "MaxStackCount raised on every lootable row"],
      ["cooldown", String(Math.round(n.cooldown * 20)), "seconds between uses"],
      ["useKey", lit("F7"), "UE4SS Key name that opens the satchel"],
    ],
    body: code`
      local readyAt = 0

      function M.onWorldReady()
          for _, entry in ipairs(Config.lootTable) do
              local row = Fx.row("DT_ItemDataTable", entry.id)
              if row and row.MaxStackCount < Config.maxStack then row.MaxStackCount = Config.maxStack end
          end
      end

      --- Weighted roll; rng is injectable so the spec can pin it.
      function M.roll(entries, rolls, rng)
          rng = rng or math.random
          local total = 0
          for _, e in ipairs(entries) do total = total + e.weight end
          local out = {}
          for _ = 1, rolls do
              local pick, acc = rng() * total, 0
              for _, e in ipairs(entries) do
                  acc = acc + e.weight
                  if pick < acc then
                      out[#out + 1] = { id = e.id, count = e.min + math.floor(rng() * (e.max - e.min + 1)) }
                      break
                  end
              end
          end
          return out
      end

      function M.use(now)
          local player = Fx.player()
          if not player or not Fx.isServer() then return end
          if now < readyAt then
              return Fx.toast(Fx.text("cooldown", "Recharging · %.1fs", readyAt - now))
          end
          readyAt = now + Config.cooldown
          for _, drop in ipairs(M.roll(Config.lootTable, Config.rolls)) do
              if Fx.give(player, drop.id, drop.count) then Fx.toast(Fx.text("loot", "+%d %s", drop.count, drop.id)) end
          end
          ${pulse(c, "player", "player")}
      end`,
    hooks: "",
    early: keyBind("useKey", "Item.use(Fx.now())"),
    strings: { ...COOLDOWN, loot: "+%d %s" },
    spec: code`
      it("rolls the requested number of stacks within bounds", function()
          local drops = M.roll(Config.lootTable, 5, function() return 0.5 end)
          assert.are.equal(5, #drops)
          for _, d in ipairs(drops) do assert.is_true(d.count >= 1) end
      end)

      it("always picks the first entry on a zero roll", function()
          local drops = M.roll(Config.lootTable, 1, function() return 0 end)
          assert.are.equal(Config.lootTable[1].id, drops[1].id)
      end)`,
  };
}

function variantMode(c: Ctx): Mode {
  const { n, pal } = c;
  return {
    file: "variants",
    local: "Variants",
    kind: "server-lua",
    persists: "Caught variants keep their lucky flag, rank and talents in the world save after the mod is removed.",
    summary: `Rolls a rare ${pal.label} variant as wild pals spawn: lucky flag, rank, talents and size.`,
    needs: ["time"],
    defs: [
      ["basePal", lit(pal.id), `DT_PalMonsterParameter row (${pal.label}); alphas use BOSS_<row>`],
      ["variantChance", String(n.chance), "roll per wild spawn"],
      ["nightBonus", (1 + n.intensity).toFixed(2), "chance multiplier between dusk and dawn"],
      ["minTalent", String(60 + (n.xp % 30)), "floor for Talent_HP / Talent_Melee / Talent_Shot (IVs, 0-100)"],
      ["rank", String(2 + (n.radius % 3)), "condenser rank (stars) the variant spawns with"],
      ["scale", (1.1 + n.speed / 2).toFixed(2), "actor scale (cosmetic)"],
    ],
    body: code`
      local variants = {} -- [actor address] = true

      function M.roll(roll, chance, night, nightBonus)
          return roll < chance * (night and nightBonus or 1)
      end

      --- Writes the replicated SaveParameter (UPalIndividualCharacterParameter.SaveParameter), so every
      --- player sees the lucky sparkle; HP is topped up to the new max on the parameter component.
      function M.apply(pal, param)
          local save = param.SaveParameter
          save.IsRarePal = true
          save.Rank = math.max(save.Rank, Config.rank)
          save.Talent_HP = math.max(save.Talent_HP, Config.minTalent)
          save.Talent_Melee = math.max(save.Talent_Melee, Config.minTalent)
          save.Talent_Shot = math.max(save.Talent_Shot, Config.minTalent)
          local comp = Fx.comp(pal)
          if comp then comp:SetHP(comp:GetMaxHP()) end
          pal:SetActorScale3D({ X = Config.scale, Y = Config.scale, Z = Config.scale })
          variants[pal:GetAddress()] = true
          Fx.toast(Fx.text("variant", "A rare %s (Lv %d) appeared", Fx.palName(pal), param:GetLevel()))
      end

      function M.onWorldReady()
          variants = {}
      end

      --- NotifyOnNewObject fires mid-construction, before the individual parameter is bound,
      --- so the roll waits a beat and re-validates on the game thread.
      function M.onSpawn(pal)
          ExecuteWithDelay(1500, function()
              ExecuteInGameThread(function()
                  if not Fx.valid(pal) or Fx.isPlayer(pal) or not Fx.isServer() then return end
                  local param = Fx.param(pal)
                  if not param then return end
                  local id = param.SaveParameter.CharacterID:ToString()
                  if id ~= Config.basePal and id ~= "BOSS_" .. Config.basePal then return end
                  if param.SaveParameter.IsRarePal or Fx.isOwned(param) then return end
                  if M.roll(math.random(), Config.variantChance, Fx.isNight(), Config.nightBonus) then
                      M.apply(pal, param)
                  end
              end)
          end)
      end

      --- Variant attacks carry the mod's effects.
      function M.onDamage(attacker, target, damage)
          if not Fx.isServer() or not Fx.valid(attacker) or not variants[attacker:GetAddress()] then return end
          ${hit(c, "target", "attacker")}
      end`,
    hooks: damageHook("Variants"),
    early: code`
      NotifyOnNewObject("/Script/Pal.PalCharacter", function(pal)
          Variants.onSpawn(pal)
      end)`,
    strings: { variant: "A rare %s (Lv %d) appeared" },
    spec: code`
      it("rolls under the chance by day", function()
          assert.is_true(M.roll(Config.variantChance / 2, Config.variantChance, false, Config.nightBonus))
          assert.is_false(M.roll(Config.variantChance * 1.01, Config.variantChance, false, Config.nightBonus))
      end)

      it("rolls more often at night", function()
          assert.is_true(M.roll(Config.variantChance * 1.01, Config.variantChance, true, Config.nightBonus))
      end)`,
  };
}

function companionMode(c: Ctx): Mode {
  const { n } = c;
  return {
    file: "companion",
    local: "Companion",
    kind: "host-lua",
    summary: "Keeps your partner pal topped up, leashed to you and fighting with the mod's effects.",
    needs: [],
    defs: [
      ["interval", String(n.interval), "seconds between partner pulses"],
      ["regenPercent", (n.power / 3).toFixed(1), "% of max HP restored per pulse"],
      ["levelBonus", "0.5", "extra regen % per 10 levels"],
      ["auraRadius", String(n.radius * 150), "radius (cm) the partner's effects reach"],
      ["leashDistance", String(n.radius * 600), "teleport the partner back beyond this (cm)"],
      ["recallKey", lit("F6"), "Ctrl + this key recalls the partner"],
    ],
    body: code`
      --- The partner pal currently out of its sphere (UPalCharacterParameterComponent::IsOtomo).
      function M.partner()
          for _, pal in ipairs(FindAllOf("PalCharacter") or {}) do
              local comp = pal:IsValid() and Fx.comp(pal)
              if comp and Fx.try("IsOtomo", function() return comp:IsOtomo() end) then return pal end
          end
      end

      --- HP (FFixedPoint64 Value) restored per pulse.
      function M.regen(maxHp, level)
          local pct = Config.regenPercent + Config.levelBonus * math.floor(level / 10)
          return math.floor(maxHp * pct / 100)
      end

      function M.onWorldReady() end

      function M.recall()
          local player, partner = Fx.player(), M.partner()
          if not player or not partner or not Fx.isServer() then return end
          local at, fwd = player:K2_GetActorLocation(), player:GetActorForwardVector()
          partner:K2_SetActorLocation({ X = at.X - fwd.X * 200, Y = at.Y - fwd.Y * 200, Z = at.Z + 30 }, false, {}, true)
          Fx.toast(Fx.text("recall", "%s is back at your side", Fx.palName(partner)))
      end

      function M.pulse()
          if not Fx.isServer() then return end
          local player, partner = Fx.player(), M.partner()
          local comp = partner and Fx.comp(partner)
          if not player or not comp then return end
          local hp, max = comp:GetHP().Value, comp:GetMaxHP().Value
          if hp < max then comp:SetHP({ Value = math.min(max, hp + M.regen(max, comp:GetLevel())) }) end
          if Fx.distance(player, partner) > Config.leashDistance then return M.recall() end
          for _, foe in ipairs(Fx.palsNear(partner, Config.auraRadius)) do
              local foeParam = Fx.param(foe)
              if foeParam and not Fx.isOwned(foeParam) then
                  ${pulse(c, "foe", "partner")}
              end
          end
      end`,
    hooks: "",
    early: [loop("Config.interval", "Companion.pulse"), keyBind("recallKey", "Companion.recall()", true)].join("\n\n"),
    strings: { recall: "%s is back at your side" },
    spec: code`
      it("scales regen with level", function()
          assert.is_true(M.regen(100000, 40) > M.regen(100000, 1))
          assert.are.equal(math.floor(100000 * Config.regenPercent / 100), M.regen(100000, 5))
      end)`,
  };
}

function mountMode(c: Ctx): Mode {
  const { n } = c;
  const mount = c.fx.includes("flight") ? { id: "JetDragon", label: "Jetragon" } : PALS.some(([re]) => re.test(c.text)) ? c.pal : { id: "Garm", label: "Direhowl" };
  return {
    file: "mount",
    local: "Mount",
    kind: "both-lua",
    summary: `Faster ${mount.label} rides: species row speed plus a keybound boost while mounted.`,
    needs: [],
    defs: [
      ["mountPal", lit(mount.id), `DT_PalMonsterParameter row (${mount.label})`],
      ["sprintMultiplier", (1 + n.speed).toFixed(2), "RideSprintSpeed / RunSpeed multiplier"],
      ["boostMultiplier", (1.4 + n.speed).toFixed(2), "MaxWalkSpeed / MaxFlySpeed multiplier during a boost"],
      ["boostSeconds", String(Math.max(2, Math.round(n.duration / 2))), "boost length"],
      ["cooldown", String(n.cooldown * 2), "seconds between boosts"],
      ["boostKey", lit("F7"), "UE4SS Key name that boosts"],
    ],
    body: code`
      local base, readyAt = nil, 0

      --- Species speeds are read when the pal is summoned, so this covers mounts called after load.
      --- Runs on the server AND on each player's PC: movement is predicted locally, and a mismatch stutters.
      function M.onWorldReady()
          local row = Fx.row("DT_PalMonsterParameter", Config.mountPal)
          if not row then return end
          base = base or { sprint = row.RideSprintSpeed, run = row.RunSpeed }
          row.RideSprintSpeed = math.floor(base.sprint * Config.sprintMultiplier)
          row.RunSpeed = math.floor(base.run * Config.sprintMultiplier)
      end

      --- UPalUtility::GetRidePal(APalPlayerCharacter) → the pal being ridden, or nil.
      local function riding(player)
          local util = Fx.util()
          local ride = util and Fx.try("GetRidePal", function() return util:GetRidePal(player) end)
          return Fx.valid(ride) and ride or nil
      end

      function M.boosted(speed)
          return speed * Config.boostMultiplier
      end

      function M.boost(now)
          local player = Fx.player()
          local ride = player and riding(player)
          if not ride then return Fx.toast(Fx.text("not_riding", "Mount up first")) end
          if now < readyAt then
              return Fx.toast(Fx.text("cooldown", "Recharging · %.1fs", readyAt - now))
          end
          readyAt = now + Config.cooldown
          local move = ride.CharacterMovement
          if not Fx.valid(move) then return end
          local walk, fly = move.MaxWalkSpeed, move.MaxFlySpeed
          move.MaxWalkSpeed, move.MaxFlySpeed = M.boosted(walk), M.boosted(fly)
          ${pulse(c, "ride", "ride")}
          ExecuteWithDelay(Config.boostSeconds * 1000, function()
              ExecuteInGameThread(function()
                  if move:IsValid() then move.MaxWalkSpeed, move.MaxFlySpeed = walk, fly end
              end)
          end)
      end`,
    hooks: "",
    early: keyBind("boostKey", "Mount.boost(Fx.now())"),
    strings: { ...COOLDOWN, not_riding: "Mount up first" },
    spec: code`
      it("boosts above the base speed", function()
          assert.is_true(M.boosted(800) > 800)
      end)`,
  };
}

function spawnsMode(c: Ctx): Mode {
  const { n, pal } = c;
  return {
    file: "spawns",
    local: "Spawns",
    kind: "server-lua",
    summary: `Higher-level wild spawns and richer ${pal.label} drops, tuned through the game's own spawn and drop tables.`,
    needs: ["time"],
    defs: [
      ["featuredPal", lit(pal.id), `DT_PalMonsterParameter row (${pal.label}) this world leans on`],
      ["levelBonus", String(1 + Math.round(n.interval / 2)), "levels added to every wild spawner entry"],
      ["levelCap", "55", "never push wild levels past this"],
      ["dropRateMultiplier", (1 + n.chance * 3).toFixed(2), "DT_PalDropItem Rate multiplier for the featured pal"],
      ["checkInterval", String(n.interval * 3), "seconds between time-of-day checks"],
    ],
    body: code`
      local baseRates, baseLevels, wasNight = {}, {}, nil

      function M.scaleLevel(level, bonus, cap)
          return math.min(cap, level + bonus)
      end

      function M.boostRate(rate, multiplier)
          return math.min(100, rate * multiplier)
      end

      --- DT_PalDropItem rows (FPalDropItemDatabaseRow): CharacterID, ItemId1..N, Rate1..N (percent).
      local function boostDrops()
          local touched = 0
          Fx.eachRow("DT_PalDropItem", function(name, row)
              if row.CharacterID:ToString() ~= Config.featuredPal then return end
              for i = 1, 10 do
                  local field = "Rate" .. i
                  local ok, rate = pcall(function() return row[field] end)
                  if not ok or type(rate) ~= "number" then break end
                  local key = name .. ":" .. i
                  baseRates[key] = baseRates[key] or rate
                  row[field] = M.boostRate(baseRates[key], Config.dropRateMultiplier)
              end
              touched = touched + 1
          end)
          Fx.log("boosted %d drop rows for %s", touched, Config.featuredPal)
      end

      --- DT_PalWildSpawner rows (FPalWildSpawnerDatabaseRow): LvMin_N / LvMax_N per slot. Applies to spawns
      --- created after the change; pals already in the world keep their level.
      local function raiseLevels()
          local touched = 0
          Fx.eachRow("DT_PalWildSpawner", function(name, row)
              for i = 1, 3 do
                  local okMin, lvMin = pcall(function() return row["LvMin_" .. i] end)
                  local okMax, lvMax = pcall(function() return row["LvMax_" .. i] end)
                  if okMin and okMax and type(lvMin) == "number" and type(lvMax) == "number" and lvMax > 0 then
                      local key = name .. ":" .. i
                      baseLevels[key] = baseLevels[key] or { lvMin, lvMax }
                      row["LvMin_" .. i] = M.scaleLevel(baseLevels[key][1], Config.levelBonus, Config.levelCap)
                      row["LvMax_" .. i] = M.scaleLevel(baseLevels[key][2], Config.levelBonus, Config.levelCap)
                  end
              end
              touched = touched + 1
          end)
          Fx.log("raised %d spawner rows by %d levels", touched, Config.levelBonus)
      end

      function M.onWorldReady()
          if not Fx.isServer() then return end
          boostDrops()
          raiseLevels()
      end

      --- Announces dusk and dawn to everyone; featured pals near any player carry the mod's effects.
      function M.watchTime()
          if not Fx.isServer() then return end
          local players = Fx.players()
          if #players == 0 then return end
          local night = Fx.isNight()
          if night ~= wasNight then
              wasNight = night
              Fx.toast(night and Fx.text("night", "Night falls · watch for %s", "${pal.label}") or Fx.text("day", "Dawn breaks"))
          end
          for _, player in ipairs(players) do
              for _, pal in ipairs(Fx.palsNear(player, 3000)) do
                  if Fx.palId(pal) == Config.featuredPal then
                      ${pulse(c, "player", "pal")}
                  end
              end
          end
      end`,
    hooks: "",
    early: loop("Config.checkInterval", "Spawns.watchTime"),
    strings: { night: "Night falls · watch for %s", day: "Dawn breaks" },
    spec: code`
      it("caps spawner levels", function()
          assert.are.equal(Config.levelCap, M.scaleLevel(Config.levelCap - 1, Config.levelBonus + 1, Config.levelCap))
          assert.are.equal(10 + Config.levelBonus, M.scaleLevel(10, Config.levelBonus, Config.levelCap))
      end)

      it("never pushes a drop rate past 100%", function()
          assert.are.equal(100, M.boostRate(90, 5))
      end)`,
  };
}

function expeditionMode(c: Ctx): Mode {
  const { n } = c;
  const loot = ["Wood", "Stone", "Leather", "Bone", "PalSphere", "Money"].map(
    (id) => `{ id = "${id}", min = ${id === "Money" ? 80 : 3}, max = ${id === "Money" ? 300 : 8 + (hashStr(id + c.cls) % 8)} },`,
  );
  return {
    file: "expedition",
    local: "Expedition",
    kind: "host-lua",
    persists: "Loot from expeditions stays in your inventory after the mod is removed; the board itself lives in the mod folder.",
    summary: "Sends idle, fed base workers on timed loot runs; the board survives restarts.",
    needs: ["give", "camp", "persist"],
    defs: [
      ["interval", String(n.interval * 3), "seconds between board ticks"],
      ["runMinutes", String(n.duration * 2), "real-time minutes per expedition"],
      ["maxParties", String(1 + (n.radius % 3)), "pals out at once"],
      ["minStomach", "60", "FullStomach a pal needs before it can leave"],
      ["lootRolls", "3", "base loot rolls (+1 per 10 levels)"],
      ["lootTable", `{\n${loot.map((e) => `    ${e}`).join("\n")}\n}`, "DT_ItemDataTable rows a run can bring back"],
      ["boardKey", lit("F6"), "Ctrl + this key shows the board"],
    ],
    body: code`
      local SAVE = "expeditions.lua"
      local board = { runs = {}, completed = 0 }

      function M.remaining(run, now)
          return math.max(0, run.started + run.duration - now)
      end

      --- Splits runs into finished and still-out.
      function M.settle(runs, now)
          local due, active = {}, {}
          for _, run in ipairs(runs) do
              table.insert(M.remaining(run, now) == 0 and due or active, run)
          end
          return due, active
      end

      function M.lootFor(run, rng)
          rng = rng or math.random
          local out = {}
          for _ = 1, Config.lootRolls + math.floor(run.level / 10) do
              local e = Config.lootTable[1 + math.floor(rng() * #Config.lootTable)]
              out[#out + 1] = { id = e.id, count = e.min + math.floor(rng() * (e.max - e.min + 1)) }
          end
          return out
      end

      --- CharacterParameterComponent.IndividualHandle.ID.InstanceId (FPalInstanceID → FGuid): stable across saves.
      local function guidOf(pal)
          local g = pal.CharacterParameterComponent.IndividualHandle.ID.InstanceId
          return string.format("%08X%08X%08X%08X", g.A & 0xFFFFFFFF, g.B & 0xFFFFFFFF, g.C & 0xFFFFFFFF, g.D & 0xFFFFFFFF)
      end

      local function isOut(id)
          for _, run in ipairs(board.runs) do
              if run.id == id then return true end
          end
          return false
      end

      --- Owned, fed workers inside a base camp with no current job (UPalCharacterParameterComponent::GetWork is nil).
      local function idleWorkers()
          local out = {}
          for _, pal in ipairs(FindAllOf("PalCharacter") or {}) do
              local param = pal:IsValid() and not Fx.isPlayer(pal) and Fx.param(pal)
              if param and Fx.isOwned(param) and param.SaveParameter.FullStomach >= Config.minStomach and Fx.inCamp(pal) then
                  local work = Fx.try("GetWork", function() return pal.CharacterParameterComponent:GetWork() end)
                  if not Fx.valid(work) and not isOut(guidOf(pal)) then out[#out + 1] = { pal = pal, param = param } end
              end
          end
          return out
      end

      local function setAway(pal, away)
          pal:SetActorHiddenInGame(away)
          pal:SetActorEnableCollision(not away)
      end

      local function welcomeBack(player, run)
          for _, item in ipairs(M.lootFor(run)) do Fx.give(player, item.id, item.count) end
          board.completed = board.completed + 1
          Fx.toast(Fx.text("returned", "%s is back from an expedition", run.name))
          for _, pal in ipairs(FindAllOf("PalCharacter") or {}) do
              local param = pal:IsValid() and Fx.param(pal)
              if param and Fx.isOwned(param) and guidOf(pal) == run.id then
                  setAway(pal, false)
                  ${pulse(c, "pal", "pal")}
              end
          end
      end

      function M.onWorldReady()
          board = Fx.load(SAVE) or board
          Fx.log("%d expeditions in the field, %d completed", #board.runs, board.completed)
      end

      --- Wall-clock time (os.time) so runs keep going while the game is closed.
      function M.tick()
          local player = Fx.player()
          if not player or not Fx.isServer() then return end
          local now = os.time()
          local due, active = M.settle(board.runs, now)
          board.runs = active
          for _, run in ipairs(due) do welcomeBack(player, run) end
          local changed = #due > 0
          for _, w in ipairs(idleWorkers()) do
              if #board.runs >= Config.maxParties then break end
              local run = { id = guidOf(w.pal), name = Fx.palName(w.pal), level = w.param:GetLevel(), started = now, duration = Config.runMinutes * 60 }
              board.runs[#board.runs + 1] = run
              setAway(w.pal, true)
              Fx.toast(Fx.text("departed", "%s left on a %d min loot run", run.name, Config.runMinutes))
              changed = true
          end
          if changed then Fx.save(SAVE, board) end
      end

      function M.show()
          local now = os.time()
          if #board.runs == 0 then return Fx.toast(Fx.text("board_empty", "Expedition board: nobody out")) end
          for _, run in ipairs(board.runs) do
              local left = M.remaining(run, now)
              Fx.toast(Fx.text("board_line", "%s · Lv %d · back in %d:%02d", run.name, run.level, left // 60, left % 60))
          end
      end

      function M.recallAll()
          for _, run in ipairs(board.runs) do run.started = 0 end
      end`,
    hooks: "",
    early: [
      loop("Config.interval", "Expedition.tick"),
      keyBind("boardKey", "Expedition.show()", true),
      code`
        RegisterConsoleCommandHandler("expedition", function(_, parameters, outputDevice)
            if parameters[1] == "recall" then Expedition.recallAll() end
            ExecuteInGameThread(Expedition.tick)
            outputDevice:Log("[${c.cls}] expedition board refreshed")
            return true
        end)`,
    ].join("\n\n"),
    strings: { returned: "%s is back from an expedition", departed: "%s left on a %d min loot run", board_empty: "Expedition board: nobody out", board_line: "%s · Lv %d · back in %d:%02d" },
    spec: code`
      it("counts down and settles finished runs", function()
          local runs = { { started = 0, duration = 60 }, { started = 50, duration = 60 } }
          assert.are.equal(0, M.remaining(runs[1], 100))
          local due, active = M.settle(runs, 100)
          assert.are.equal(1, #due)
          assert.are.equal(1, #active)
      end)

      it("rolls more loot for higher-level pals", function()
          local rng = function() return 0 end
          assert.is_true(#M.lootFor({ level = 30 }, rng) > #M.lootFor({ level = 1 }, rng))
      end)

      it("round-trips the board through the serializer", function()
          local text = Fx.serialize({ runs = { { id = "A1", started = 5 } }, completed = 2 })
          local data = load("return " .. text)()
          assert.are.equal("A1", data.runs[1].id)
          assert.are.equal(2, data.completed)
      end)`,
  };
}

function worksiteMode(c: Ctx): Mode {
  const { n } = c;
  return {
    file: "worksite",
    local: "Worksite",
    kind: "server-lua",
    summary: "A base-camp loop that pushes job progress forward and buffs the crew; runs on the server for everyone.",
    needs: ["camp"],
    defs: [
      ["interval", String(n.interval), "seconds between base ticks"],
      ["progressBoost", (n.chance / 4).toFixed(3), "fraction of RequiredWorkAmount added per tick"],
      ["reportKey", lit("F6"), "Ctrl + this key prints the base report (single-player / host)"],
    ],
    body: code`
      local last = { camps = 0, jobs = 0, crew = 0 }

      function M.advance(current, required, boost)
          return math.min(required, current + required * boost)
      end

      function M.onWorldReady() end

      --- UPalWorkProgress.CurrentWorkAmount / RequiredWorkAmount (replicated from the server).
      function M.tick()
          if not Fx.isServer() or #Fx.players() == 0 then return end
          local camps = FindAllOf("PalBaseCampModel") or {}
          if #camps == 0 then return end
          local jobs, crew = 0, 0
          for _, work in ipairs(FindAllOf("PalWorkProgress") or {}) do
              if work:IsValid() and work.RequiredWorkAmount > 0 and work.CurrentWorkAmount < work.RequiredWorkAmount then
                  work.CurrentWorkAmount = M.advance(work.CurrentWorkAmount, work.RequiredWorkAmount, Config.progressBoost)
                  jobs = jobs + 1
              end
          end
          for _, pal in ipairs(FindAllOf("PalCharacter") or {}) do
              local param = pal:IsValid() and not Fx.isPlayer(pal) and Fx.param(pal)
              if param and Fx.isOwned(param) and Fx.inCamp(pal) then
                  ${pulse(c, "pal", "pal")}
                  crew = crew + 1
              end
          end
          last = { camps = #camps, jobs = jobs, crew = crew }
      end

      function M.report()
          Fx.toast(Fx.text("report", "%d camps · %d jobs pushed · %d pals on shift", last.camps, last.jobs, last.crew))
      end`,
    hooks: "",
    early: [loop("Config.interval", "Worksite.tick"), keyBind("reportKey", "Worksite.report()", true)].join("\n\n"),
    strings: { report: "%d camps · %d jobs pushed · %d pals on shift" },
    spec: code`
      it("advances work without overshooting", function()
          assert.are.equal(100, M.advance(99, 100, 0.5))
          assert.are.equal(10 + 100 * Config.progressBoost, M.advance(10, 100, Config.progressBoost))
      end)`,
  };
}

function questMode(c: Ctx): Mode {
  const { n, pal } = c;
  return {
    file: "quests",
    local: "Quests",
    kind: "host-lua",
    persists: "Quest rewards stay in your inventory after the mod is removed; progress lives in the mod folder.",
    summary: `A three-stage questline polled from game state, persisted next to the mod.`,
    needs: ["give", "camp", "persist", "time"],
    defs: [
      ["featuredPal", lit(pal.id), `the ${pal.label} the night stage tracks`],
      [
        "stages",
        `{\n    { id = "level", goal = ${10 + (n.xp % 15)}, reward = { id = "PalSphere_Mega", count = 5 } },\n    { id = "night_watch", goal = ${n.duration * 15}, reward = { id = "Money", count = ${n.health} } },\n    { id = "camp", goal = ${4 + (n.radius % 5)}, reward = { id = "PalSphere_Giga", count = 3 } },\n}`,
        "stage goals: player level, seconds near the featured pal at night, workers in camp",
      ],
      ["watchRadius", String(n.radius * 400), "how close (cm) counts as near the featured pal"],
      ["interval", "5", "seconds between objective checks"],
      ["journalKey", lit("F6"), "Ctrl + this key shows the journal"],
    ],
    body: code`
      local SAVE = "quest_log.lua"
      local log = { stage = 1, value = 0 }

      --- Pure: applies one tick of facts; returns the index of a stage completed this tick.
      function M.advance(state, facts, dt)
          local stage = Config.stages[state.stage]
          if not stage then return nil end
          if stage.id == "level" then
              state.value = facts.level
          elseif stage.id == "night_watch" then
              if facts.nearFeaturedAtNight then state.value = state.value + dt end
          elseif stage.id == "camp" then
              state.value = facts.workers
          end
          if state.value < stage.goal then return nil end
          local done = state.stage
          state.stage, state.value = state.stage + 1, 0
          return done
      end

      local function facts(player)
          local comp = Fx.comp(player)
          if not comp then return nil end
          local near = false
          if Fx.isNight() then
              for _, p in ipairs(Fx.palsNear(player, Config.watchRadius)) do
                  if Fx.palId(p) == Config.featuredPal then near = true break end
              end
          end
          local workers = 0
          for _, p in ipairs(FindAllOf("PalCharacter") or {}) do
              local pp = p:IsValid() and not Fx.isPlayer(p) and Fx.param(p)
              if pp and Fx.isOwned(pp) and Fx.inCamp(p) then workers = workers + 1 end
          end
          return { level = comp:GetLevel(), nearFeaturedAtNight = near, workers = workers }
      end

      function M.onWorldReady()
          log = Fx.load(SAVE) or log
      end

      function M.tick()
          local player = Fx.player()
          local f = player and Fx.isServer() and facts(player)
          if not f then return end
          local done = M.advance(log, f, Config.interval)
          if not done then return end
          local stage = Config.stages[done]
          Fx.give(player, stage.reward.id, stage.reward.count)
          Fx.toast(Fx.text("stage_done", "${c.input.modName} · %s complete", Fx.text(stage.id, stage.id)))
          for _, foe in ipairs(Fx.palsNear(player, 1500)) do
              local fp = Fx.param(foe)
              if fp and not Fx.isOwned(fp) then
                  ${pulse(c, "foe", "player")}
              end
          end
          Fx.save(SAVE, log)
      end

      function M.journal()
          local stage = Config.stages[log.stage]
          if not stage then return Fx.toast(Fx.text("finished", "${c.input.modName} · all stages complete")) end
          Fx.toast(Fx.text("progress", "%s · %d / %d", Fx.text(stage.id, stage.id), math.floor(log.value), stage.goal))
      end`,
    hooks: code`
      -- Typing !quest in chat opens the journal too (APalPlayerState::EnterChat(FText Msg, EPalChatCategory)).
      RegisterHook("/Script/Pal.PalPlayerState:EnterChat", function(self, message)
          local ok, text = pcall(function() return message:get():ToString() end)
          if ok and text:lower() == "!quest" then ExecuteInGameThread(Quests.journal) end
      end)`,
    early: [loop("Config.interval", "Quests.tick"), keyBind("journalKey", "Quests.journal()", true)].join("\n\n"),
    strings: {
      level: "Reach the trainer's level",
      night_watch: `Shadow a ${pal.label} after dark`,
      camp: "Staff your base",
      stage_done: `${c.input.modName} · %s complete`,
      progress: "%s · %d / %d",
      finished: `${c.input.modName} · all stages complete`,
    },
    spec: code`
      it("completes the level stage once the player reaches the goal", function()
          local state = { stage = 1, value = 0 }
          assert.is_nil(M.advance(state, { level = 1, workers = 0 }, 5))
          assert.are.equal(1, M.advance(state, { level = Config.stages[1].goal, workers = 0 }, 5))
          assert.are.equal(2, state.stage)
      end)

      it("only counts night-watch time near the featured pal", function()
          local state = { stage = 2, value = 0 }
          M.advance(state, { nearFeaturedAtNight = false }, 5)
          assert.are.equal(0, state.value)
          M.advance(state, { nearFeaturedAtNight = true }, 5)
          assert.are.equal(5, state.value)
      end)`,
  };
}

function overlayMode(c: Ctx): Mode {
  const { n } = c;
  return {
    file: "overlay",
    local: "Overlay",
    kind: "client-lua",
    summary: "Look at a pal to read its IVs, passives and work speed; pin it to keep it refreshing.",
    needs: [],
    ue: true,
    fx: false,
    defs: [
      ["focusRange", String(n.radius * 500), "max distance (cm) to inspect"],
      ["focusCone", "0.92", "min dot product between view and pal (≈23°)"],
      ["refreshMs", String(n.interval * 250), "pinned refresh rate"],
      ["inspectKey", lit("F7"), "UE4SS Key name that inspects the pal under the crosshair"],
      ["pinKey", lit("F6"), "Ctrl + this key pins / unpins the overlay"],
    ],
    body: code`
      local pinned, lastFocus = false, nil

      --- Pure: the candidate closest to the view ray inside the cone, nearer ones winning ties.
      function M.pickFocus(eye, forward, candidates, maxDistance, minDot)
          local best, bestScore
          for _, c in ipairs(candidates) do
              local dx, dy, dz = c.pos.X - eye.X, c.pos.Y - eye.Y, c.pos.Z - eye.Z
              local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
              if dist > 0 and dist <= maxDistance then
                  local dot = (dx * forward.X + dy * forward.Y + dz * forward.Z) / dist
                  local score = dot - 0.1 * dist / maxDistance
                  if dot >= minDot and (not bestScore or score > bestScore) then best, bestScore = c, score end
              end
          end
          return best
      end

      function M.format(s)
          return {
              string.format("%s  Lv %d%s", s.name, s.level, s.lucky and "  ★" or ""),
              string.format("HP %d/%d · IV %d/%d/%d/%d", s.hp, s.maxHp, s.talentHp, s.talentMelee, s.talentShot, s.talentDefense),
              string.format("Work %d · %s", s.craftSpeed, #s.passives > 0 and table.concat(s.passives, ", ") or "no passives"),
          }
      end

      --- Reads only (SaveParameter is replicated, so this works on any client).
      local function statsOf(pal)
          local comp, param = Fx.comp(pal), Fx.param(pal)
          if not comp or not param then return nil end
          local save, passives = param.SaveParameter, {}
          save.PassiveSkillList:ForEach(function(_, skill) passives[#passives + 1] = skill:get():ToString() end)
          return {
              name = Fx.palName(pal), level = comp:GetLevel(), lucky = save.IsRarePal,
              hp = comp:GetHP().Value // 1000, maxHp = comp:GetMaxHP().Value // 1000,
              talentHp = save.Talent_HP, talentMelee = save.Talent_Melee, talentShot = save.Talent_Shot, talentDefense = save.Talent_Defense,
              craftSpeed = save.CraftSpeed, passives = passives,
          }
      end

      function M.onWorldReady()
          lastFocus = nil
      end

      --- Shown in the UE4SS console/log on a client (in-game notices are a server broadcast).
      local function show(line)
          if Fx.isServer() then Fx.toast(line) else Fx.log("%s", line) end
      end

      function M.inspect()
          local controller = UEHelpers.GetPlayerController()
          local camera = Fx.valid(controller) and controller.PlayerCameraManager
          if not Fx.valid(camera) then return end
          local eye = camera:GetCameraLocation()
          local forward = UEHelpers.GetKismetMathLibrary():GetForwardVector(camera:GetCameraRotation())
          local candidates = {}
          for _, pal in ipairs(FindAllOf("PalCharacter") or {}) do
              if pal:IsValid() and not Fx.isPlayer(pal) then candidates[#candidates + 1] = { actor = pal, pos = pal:K2_GetActorLocation() } end
          end
          local focus = M.pickFocus(eye, forward, candidates, Config.focusRange, Config.focusCone)
          if not focus or (pinned and focus.actor:GetAddress() == lastFocus) then return end
          lastFocus = focus.actor:GetAddress()
          local stats = Fx.try("pal stats", function() return statsOf(focus.actor) end)
          if stats then
              for _, line in ipairs(M.format(stats)) do show(line) end
          end
      end

      function M.togglePin()
          pinned = not pinned
          lastFocus = nil
          show(Fx.text(pinned and "pinned" or "unpinned", pinned and "Overlay pinned" or "Overlay unpinned"))
      end

      function M.isPinned()
          return pinned
      end`,
    hooks: "",
    early: [
      keyBind("inspectKey", "Overlay.inspect()"),
      keyBind("pinKey", "Overlay.togglePin()", true),
      code`
        -- UE4SS Lua has no draw API, so the overlay uses notices/log lines and refreshes while pinned.
        LoopAsync(Config.refreshMs, function()
            if Overlay.isPinned() then ExecuteInGameThread(Overlay.inspect) end
            return false
        end)`,
    ].join("\n\n"),
    strings: { pinned: "Overlay pinned", unpinned: "Overlay unpinned" },
    spec: code`
      local eye, fwd = { X = 0, Y = 0, Z = 0 }, { X = 1, Y = 0, Z = 0 }

      it("focuses the pal in front of the camera", function()
          local ahead, behind = { pos = { X = 500, Y = 10, Z = 0 } }, { pos = { X = -500, Y = 0, Z = 0 } }
          assert.are.equal(ahead, M.pickFocus(eye, fwd, { behind, ahead }, Config.focusRange, Config.focusCone))
      end)

      it("ignores pals out of range", function()
          assert.is_nil(M.pickFocus(eye, fwd, { { pos = { X = Config.focusRange * 2, Y = 0, Z = 0 } } }, Config.focusRange, Config.focusCone))
      end)

      it("formats a three-line panel", function()
          local lines = M.format({ name = "Lamball", level = 12, lucky = true, hp = 300, maxHp = 410, talentHp = 80, talentMelee = 50, talentShot = 40, talentDefense = 70, craftSpeed = 100, passives = { "CraftSpeed_up1" } })
          assert.are.equal(3, #lines)
          assert.truthy(lines[1]:find("★"))
      end)`,
  };
}

