const EXPEDITION = /expedition|idle pals?|loot runs?|dispatch|scouting|errand|forag/;

function modeFor(c: Ctx): Mode {
  const k = c.input.category.key;
  // "Loot" routes expedition boards to Items; the prompt still describes a base system.
  if ((k === "items" || k === "mechanics") && EXPEDITION.test(c.text)) return expeditionMode(c);
  switch (ARCH[k]) {
    case "item":
      return k === "weapons" ? weaponMode(c) : k === "magic" ? spellMode(c) : itemMode(c);
    case "entity":
      return k === "vehicles" ? mountMode(c) : k === "characters" ? companionMode(c) : variantMode(c);
    case "world":
      return spawnsMode(c);
    case "visual":
      return postFxMode(c);
    default:
      if (k === "quests") return questMode(c);
      if (k === "interface") return overlayMode(c);
      if (k === "audio") return audioMode(c);
      return worksiteMode(c);
  }
}

const tableLines = (defs: Def[]) => defs.map(([k, v, note]) => (v.includes("\n") ? `-- ${note}\n${k} = ${v},` : `${k} = ${v}, -- ${note}`));

/** Official loader PackageName: letters and digits only, stable for the mod's lifetime (updates replace it). */
export function palworldPackageName(modName: string): string {
  const { cls } = identity(modName);
  const suffix = hashStr(`palworld|${cls}`).toString(36).toUpperCase().slice(0, 4);
  return `${cls.replace(/[^A-Za-z0-9]/g, "").slice(0, 56)}${suffix}`;
}

/** Pocketpair's Info.json (PalModLoader FPalModInfoStruct). Lua rule for clients; IsServer rule only when it can run on a server. */
export function palworldInfoJson(input: TemplateInput, kind: LuaKind, description: string) {
  const server = kind === "server-lua" || kind === "both-lua";
  return {
    ModName: input.modName,
    PackageName: palworldPackageName(input.modName),
    Author: "Cyrus",
    Description: description,
    Version: `${input.version}.0.0`,
    DebugMode: false,
    MinRevision: PALWORLD_MIN_REVISION,
    Dependencies: [PALWORLD_UE4SS_PACKAGE],
    Tags: [kind === "client-lua" ? "User Interface" : "Gameplay", "UE4SS"],
    InstallRule: [{ Type: "Lua", Targets: ["./Scripts"] }, ...(server ? [{ Type: "Lua", IsServer: true, Targets: ["./Scripts"] }] : [])],
  };
}

export type PalworldManifest = {
  schema: "cyrus.palworld/1";
  generator: string;
  kind: PalworldModKind;
  side: "server" | "client" | "both";
  label: string;
  installNote: string;
  worksOnNxeonServers: boolean;
  game: { version: string; minRevision: number };
  loader: string;
  dependencies: string[];
  persistsInWorld: string | null;
  templatePreview: string | null;
  settings?: { key: string; value: number | boolean | string; label: string }[];
  warnings: string[];
};

function manifest(kind: PalworldModKind, extra: Partial<PalworldManifest> = {}): PalworldManifest {
  const k = PALWORLD_KINDS[kind];
  return {
    schema: "cyrus.palworld/1",
    generator: PALWORLD_GENERATOR,
    kind,
    side: k.side,
    label: k.label,
    installNote: k.reason,
    worksOnNxeonServers: k.nxeonServers,
    game: { version: PALWORLD_CURRENT_VERSION, minRevision: PALWORLD_MIN_REVISION },
    loader: kind === "server-settings" ? "None (PalWorldSettings.ini)" : support.loader.name,
    dependencies: kind === "server-settings" ? [] : [PALWORLD_UE4SS_PACKAGE],
    persistsInWorld: null,
    templatePreview: null,
    warnings: [],
    ...extra,
  };
}

const json = (v: unknown) => `${JSON.stringify(v, null, 2)}\n`;

/** A server settings preset: no code, nothing for players to install, works on Linux servers. */
function settingsMod(input: TemplateInput, changes: SettingsChange[]): Built {
  const issues = validateSettingsChanges(changes);
  const rows = changes.map((c) => ({ key: c.key, value: c.value, label: SETTING_BY_KEY[c.key]?.label ?? c.key }));
  const patch = file(
    "PalWorldSettings.patch.ini",
    `; ${input.modName} · Palworld server settings preset (Cyrus ${MODEL_NAME[input.model]}, v${input.version})\n` +
      `; Only the keys below change. MERGE them into the OptionSettings line of\n` +
      `; Pal/Saved/Config/LinuxServer/PalWorldSettings.ini (WindowsServer on Windows) with the server STOPPED.\n` +
      `; Do not paste this over the whole file: keys missing from the line reset to their defaults.\n` +
      rows.map((r) => `;   ${r.label}: ${r.key} = ${String(r.value)}`).join("\n") +
      `\n${renderPresetFragment(changes)}`,
  );
  const meta = file("Cyrus.json", json(manifest("server-settings", { settings: rows, warnings: issues.map((i) => `${i.severity}: ${i.message}`) })));
  const notes = file(
    "NOTES.md",
    code`
      # ${input.modName}

      Palworld **server settings preset** for Palworld ${PALWORLD_CURRENT_VERSION}. Players don't install anything; it works on Linux and Windows dedicated servers, and for console players who join.

      ${rows.map((r) => `- **${r.label}** (\`${r.key}\`) → \`${String(r.value)}\``)}

      ## Apply

      1. Stop the server.
      2. Merge the keys from \`PalWorldSettings.patch.ini\` into the \`OptionSettings=(...)\` line of \`Pal/Saved/Config/LinuxServer/PalWorldSettings.ini\` (keep every other key).
      3. Start the server.

      On Nxeon, settings that have a panel field can be set there; for the rest, turn on "edit the config file myself" first, or the server regenerates the file on every start.
      ${issues.length ? `\n## Check before applying\n\n${issues.map((i) => `- ${i.message}`).join("\n")}` : ""}`,
  );
  const test = file("spec/settings.json", json({ changes, issues }));
  return { files: [meta, patch, notes], test, essential: 2, install: installFor("server-settings") };
}

export function palworldUE4SS(input: TemplateInput): Built {
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  const changes = settingsIntent(text);
  if (changes.length) return settingsMod(input, changes);

  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const effects = effectsFor(input);
  const fx = effects.map((e) => e.key);
  const c: Ctx = { input, n, cls, snake, fx, pal: pickPal(input, fx), text };
  const mode = modeFor(c);
  const usesFx = mode.fx !== false;
  const needs = new Set([...mode.needs, ...(usesFx ? fx.flatMap((k) => FX[k].needs) : [])]);
  const own = new Set(mode.defs.map(([k]) => k));
  const allCode = `${mode.body}\n${mode.hooks}\n${mode.early ?? ""}`;
  // Effect tunables only ship when a snippet in this module actually reads them.
  const defs = [...mode.defs, ...(usesFx ? fxDefs(fx, n).filter(([k]) => !own.has(k) && allCode.includes(`Config.${k}`)) : [])];
  const strings: Record<string, string> = { ...mode.strings, ...(usesFx && fx.includes("neon") ? { hit: "%s  -%d", pulse: "%s ▸ surge" } : {}) };
  const local = mode.local;
  const kind = PALWORLD_KINDS[mode.kind];
  const vNote = input.version > 1 ? `-- v${input.version}: retuned numbers${input.model !== "katara" ? ", all exposed in config.lua" : ""}` : "";

  const main = file(
    "Scripts/main.lua",
    code`
      --[[
          ${input.modName}
          ${input.category.label} mod for Palworld ${PALWORLD_CURRENT_VERSION} · UE4SS (Lua 5.4) via the official mod loader
          Runs on: ${kind.label} (${mode.kind})
          Forged by Cyrus (${MODEL_NAME[input.model]}) · v${input.version}
          ${usesFx ? `Effects: ${effects.map((e) => e.label.toLowerCase()).join("; ")}` : ""}
      ]]
      ${vNote}

      local Fx = require("${snake}.effects")
      local ${local} = require("${snake}.${mode.file}")

      local Config = Fx.loadConfig(${local}.DEFAULTS)
      ${local}.init(Config)

      -- UFunction hooks need their class in memory, so they are registered once, on the first ready world.
      local hooked = false
      local function registerHooks()
          if hooked then return end
          hooked = true
          ${mode.hooks || "-- (no UFunction hooks)"}
      end

      -- One "world is ready" signal for every side: InitGameState fires on servers and the co-op host,
      -- PlayerController:ClientRestart fires on a player's PC when the local pawn is (re)possessed.
      local readyWorld = nil
      local function worldReady()
          local world = Fx.world()
          local key = Fx.valid(world) and world:GetAddress() or 0
          if key == readyWorld then return end
          readyWorld = key
          ExecuteWithDelay(2000, function()
              ExecuteInGameThread(function()
                  registerHooks()
                  ${local}.onWorldReady()
              end)
          end)
      end

      RegisterInitGameStatePostHook(function()
          worldReady()
      end)

      RegisterHook("/Script/Engine.PlayerController:ClientRestart", function(self)
          local controller = self:get()
          if Fx.valid(controller) and controller:IsLocalController() then worldReady() end
      end)

      ${mode.early ?? ""}

      Fx.log("v${input.version} loaded (${ARCH[input.category.key]} · ${mode.file} · ${mode.kind})")`,
  );

  const core = file(
    `Scripts/${snake}/${mode.file}.lua`,
    code`
      --[[
          ${input.modName} · ${mode.file}.lua
          ${mode.summary}
      ]]
      ${mode.ue ? 'local UEHelpers = require("UEHelpers")' : ""}
      local Fx = require("${snake}.effects")

      local M = {}
      local Config = {}

      M.DEFAULTS = {
          ${tableLines(defs)}
      }

      function M.init(config)
          Config = config
      end

      ${mode.body}

      return M`,
  );

  const config = file(
    `Scripts/${snake}/config.lua`,
    code`
      -- ${input.modName} · config.lua
      -- Overrides for ${mode.file}.lua; delete a line to fall back to its default. Restart the game or server after editing.
      return {
          ${tableLines(defs)}
          language = "en", -- loads lang/<language>.lua
      }`,
  );

  const l10n = file(
    `Scripts/${snake}/lang/en.lua`,
    code`
      -- ${input.modName} · English strings.
      -- Copy to lang/<code>.lua to translate, then set language in config.lua. Keep the % placeholders.
      return {
          name = ${lit(input.modName)},
          ${Object.entries(strings).map(([k, v]) => `${k} = ${lit(v)},`)}
      }`,
  );

  const test = file(
    `spec/${snake}_spec.lua`,
    code`
      -- busted spec for ${input.modName} · run \`busted\` from the mod folder (pure logic only, no game needed)
      package.path = "./Scripts/?.lua;" .. package.path

      -- Just enough UE4SS surface for the modules to load outside the game.
      _G.RegisterHook = function() end
      _G.RegisterInitGameStatePostHook = function() end
      _G.NotifyOnNewObject = function() end
      _G.RegisterKeyBind = function() end
      _G.RegisterConsoleCommandHandler = function() end
      _G.LoopAsync = function() end
      _G.ExecuteWithDelay = function(_, fn) fn() end
      _G.ExecuteInGameThread = function(fn) fn() end
      _G.StaticFindObject = function() return nil end
      _G.FindObject = function() return nil end
      _G.FindFirstOf = function() return nil end
      _G.FindAllOf = function() return nil end
      _G.FName = function(s) return s end
      _G.Key = setmetatable({}, { __index = function(_, k) return k end })
      _G.ModifierKey = { CONTROL = "CONTROL" }
      package.preload["UEHelpers"] = function()
          local none = function() return nil end
          return { GetPlayerController = none, GetWorld = none, GetGameplayStatics = none, GetKismetSystemLibrary = none, GetKismetMathLibrary = none }
      end

      local Fx = require("${snake}.effects")
      local M = require("${snake}.${mode.file}")
      local Config = Fx.loadConfig(M.DEFAULTS)
      M.init(Config)

      describe("${input.modName}", function()
          ${mode.spec}

          it("ships non-negative numeric defaults", function()
              for key, value in pairs(M.DEFAULTS) do
                  if type(value) == "number" then assert.is_true(value >= 0, key) end
              end
          end)
      end)`,
  );

  const warnings = [
    ...(kind.nxeonServers ? [] : ["Can't be installed on Nxeon's Linux Palworld servers yet: the official mod loader and UE4SS server mods are Windows-only."]),
    ...(mode.kind === "both-lua" ? ["Every player must install it too, or they see stutter and old values."] : []),
    ...(mode.preview ? [mode.preview] : []),
  ];
  const info = file("Info.json", json(palworldInfoJson(input, mode.kind, mode.summary)));
  const meta = file("Cyrus.json", json(manifest(mode.kind, { persistsInWorld: mode.persists ?? null, templatePreview: mode.preview ?? null, warnings })));

  const files: ModFile[] = [main, core, file(`Scripts/${snake}/effects.lua`, effectsModule(input, snake, cls, needs)), info, meta, file("enabled.txt", "")];
  return { files, config, l10n, test, essential: 5, install: installFor(mode.kind) };
}

/** Plain install steps for the README, by where the mod runs. */
export function installFor(kind: PalworldModKind): string[] {
  if (kind === "server-settings") return ["Stop the server.", "Merge `PalWorldSettings.patch.ini` into the OptionSettings line of `PalWorldSettings.ini` (keep every other key).", "Start the server. Players install nothing."];
  const client = [
    "On a Windows PC with Palworld on Steam, subscribe to the \"UE4SS\" package on the Steam Workshop (the Palworld build).",
    "Copy this folder into `steamapps/workshop/content/1623730/<any-folder>/` so Info.json sits at its top.",
    "In Palworld open Mod Management, allow mods, enable this mod and restart the game.",
  ];
  const server = [
    "Windows dedicated server only: put this folder in `Mods/Workshop/<folder>/` next to PalServer.exe, together with the UE4SS package.",
    "In `Mods/PalModSettings.ini` under `[PalModSettings]` set `bGlobalEnableMod=True` and add `ActiveModList=UE4SS` and `ActiveModList=<PackageName from Info.json>`.",
    "Restart the server. Linux servers (including Nxeon's) can't load it yet.",
  ];
  if (kind === "server-lua") return [...server, "Optional: players can install it too to use it in single-player."];
  if (kind === "both-lua") return [...server, ...client];
  return client;
}

