input.content:
/**
 * Static validator for Cyrus Palworld output (PURE, no game files needed). Runs on every build before the
 * customer sees it. Checks the package against Pocketpair's official loader format, Cyrus's own manifest,
 * Lua block structure, blocked / flagged APIs, the knowledge pack's known failure patterns, file-access
 * confinement and, for settings presets, every key against the documented settings.
 */
import support, { PALWORLD_KINDS, PALWORLD_UE4SS_PACKAGE, type PalworldModKind } from "./palworld";
import { parseOptionSettings, SETTING_BY_KEY, validateSettingsChanges, type SettingsChange } from "./palworld.settings";

export type PalworldIssue = { severity: "error" | "warn"; code: string; message: string; path?: string; line?: number };
export type PalworldValidation = { ok: boolean; kind: PalworldModKind | null; errors: PalworldIssue[]; warnings: PalworldIssue[] };
type FileLike = { path: string; content: string };

const INSTALL_TYPES = new Set(["Paks", "Lua", "LogicMods", "UE4SS", "PalSchema"]);
const KINDS = new Set(Object.keys(PALWORLD_KINDS));
const MAX_FILE_BYTES = 256 * 1024;

/** UFunction hooks Cyrus has verified in the published headers (anything else is flagged for review). */
export const VERIFIED_HOOKS = new Set([
  "/Script/Engine.PlayerController:ClientRestart",
  "/Script/Pal.PalDamageReactionComponent:CallOnActualDamageProcessed_ToAll",
  "/Script/Pal.PalPlayerState:EnterChat",
]);

/* ───────────── Lua lexing helpers ───────────── */

/**
 * Replaces comments with spaces and string contents with `S` placeholders (keeping newlines so line
 * numbers survive). `keepStrings` keeps string bodies (for patterns like "SaveGames").
 */
export function stripLua(src: string, keepStrings = false): string {
  let out = "";
  let i = 0;
  const longOpen = (at: number) => {
    const m = /^\[(=*)\[/.exec(src.slice(at, at + 64));
    return m ? m[1].length : -1;
  };
  const blank = (s: string) => s.replace(/[^\n]/g, " ");
  while (i < src.length) {
    const ch = src[i];
    if (ch === "-" && src[i + 1] === "-") {
      const level = longOpen(i + 2);
      if (level >= 0) {
        const close = `]${"=".repeat(level)}]`;
        const end = src.indexOf(close, i + 4 + level);
        const stop = end < 0 ? src.length : end + close.length;
        out += blank(src.slice(i, stop));
        i = stop;
      } else {
        const end = src.indexOf("\n", i);
        const stop = end < 0 ? src.length : end;
        out += blank(src.slice(i, stop));
        i = stop;
      }
      continue;
    }
    if (ch === "[") {
      const level = longOpen(i);
      if (level >= 0) {
        const close = `]${"=".repeat(level)}]`;
        const end = src.indexOf(close, i + 2 + level);
        const stop = end < 0 ? src.length : end + close.length;
        const body = src.slice(i, stop);
        out += keepStrings ? body : `"${blank(body.slice(1, -1)).replace(/ /g, "S")}"`;
        i = stop;
        continue;
      }
    }
    if (ch === '"' || ch === "'") {
      let j = i + 1;
      while (j < src.length && src[j] !== ch && src[j] !== "\n") j += src[j] === "\\" ? 2 : 1;
      const body = src.slice(i, j + 1);
      out += keepStrings ? body : `${ch}${"S".repeat(Math.max(0, body.length - 2))}${ch}`;
      i = j + 1;
      continue;
    }
    out += ch;
    i++;
  }
  return out;
}

/** Checks that function/if/do/repeat blocks close (end/until) in order. Returns the first problem, if any. */
export function luaBlockProblem(src: string): { line: number; message: string } | null {
  const code = stripLua(src);
  const stack: { word: string; line: number }[] = [];
  const re = /\b(function|if|do|repeat|end|until|while|for)\b/g;
  let m: RegExpExecArray | null;
  let pendingLoop = 0; // `for`/`while` whose `do` is still ahead
  const lineAt = (idx: number) => code.slice(0, idx).split("\n").length;
  while ((m = re.exec(code))) {
    const w = m[1];
    const line = lineAt(m.index);
    if (w === "for" || w === "while") pendingLoop++;
    else if (w === "do") {
      if (pendingLoop > 0) pendingLoop--;
      stack.push({ word: "do", line });
    } else if (w === "function" || w === "if" || w === "repeat") stack.push({ word: w, line });
    else if (w === "end") {
      const top = stack.pop();
      if (!top || top.word === "repeat") return { line, message: top ? `\`end\` closes a \`repeat\` opened on line ${top.line}` : "`end` without an open block" };
    } else if (w === "until") {
      const top = stack.pop();
      if (!top || top.word !== "repeat") return { line, message: "`until` without a matching `repeat`" };
    }
  }
  if (stack.length) {
    const top = stack[stack.length - 1];
    return { line: top.line, message: `\`${top.word}\` opened on line ${top.line} is never closed` };
  }
  return null;
}

/** Brackets and parentheses balance (outside strings and comments). */
export function luaBracketProblem(src: string): { line: number; message: string } | null {
  const code = stripLua(src);
  const pairs: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
  const stack: { ch: string; line: number }[] = [];
  let line = 1;
  for (const ch of code) {
    if (ch === "\n") line++;
    else if (ch === "(" || ch === "[" || ch === "{") stack.push({ ch, line });
    else if (ch in pairs) {
      const top = stack.pop();
      if (!top || top.ch !== pairs[ch]) return { line, message: `unbalanced \`${ch}\`` };
    }
  }
  return stack.length ? { line: stack[stack.length - 1].line, message: `\`${stack[stack.length - 1].ch}\` is never closed` } : null;
}

const lineOf = (src: string, idx: number) => src.slice(0, idx).split("\n").length;

/* ───────────── value parsing for settings presets ───────────── */

function typedValue(key: string, raw: string): SettingsChange["value"] {
  const spec = SETTING_BY_KEY[key];
  const v = raw.trim();
  if (spec?.kind === "bool" || /^(true|false)$/i.test(v)) return /^true$/i.test(v) ? true : /^false$/i.test(v) ? false : v;
  if (spec?.kind === "enum") return v.replace(/^"|"$/g, "");
  const n = Number(v);
  return v !== "" && Number.isFinite(n) ? n : v.replace(/^"|"$/g, "");
}

/* ───────────── the validator ───────────── */

export function validatePalworldMod(files: FileLike[]): PalworldValidation {
  const errors: PalworldIssue[] = [];
  const warnings: PalworldIssue[] = [];
  const add = (i: PalworldIssue) => (i.severity === "error" ? errors : warnings).push(i);
  const byPath = new Map(files.map((f) => [f.path, f]));

  for (const f of files) {
    if (f.path.startsWith("/") || /(^|\/)\.\.(\/|$)/.test(f.path) || /^[A-Za-z]:/.test(f.path) || f.path.includes("\\"))
      add({ severity: "error", code: "path", path: f.path, message: "File paths must be relative and stay inside the mod folder." });
    if (f.content.length > MAX_FILE_BYTES) add({ severity: "error", code: "size", path: f.path, message: "File is too large for a Cyrus mod." });
  }

  // Cyrus manifest
  let kind: PalworldModKind | null = null;
  const metaFile = byPath.get("Cyrus.json");
  if (!metaFile) add({ severity: "error", code: "manifest", message: "Cyrus.json is missing (Cyrus can't tell where this mod runs)." });
  else {
    try {
      const meta = JSON.parse(metaFile.content);
      if (meta.schema !== "cyrus.palworld/1") add({ severity: "error", code: "manifest", path: "Cyrus.json", message: "Cyrus.json has an unknown schema." });
      if (!KINDS.has(meta.kind)) add({ severity: "error", code: "manifest", path: "Cyrus.json", message: "Cyrus.json kind must be server-settings, server-lua, both-lua, host-lua or client-lua." });
      else kind = meta.kind;
      if (kind && meta.side !== PALWORLD_KINDS[kind].side) add({ severity: "error", code: "manifest", path: "Cyrus.json", message: `side must be "${PALWORLD_KINDS[kind].side}" for a ${kind} mod.` });
      if (!meta.game || typeof meta.game.version !== "string" || !meta.game.version) add({ severity: "error", code: "version", path: "Cyrus.json", message: "Cyrus.json must name the target game version." });
      else if (!support.versions.some((v) => v.version === meta.game.version && v.status === "current"))
        add({ severity: "warn", code: "outdated", path: "Cyrus.json", message: `Built for Palworld ${meta.game.version}, which is not the current version; it may need an update.` });
      if (kind && meta.worksOnNxeonServers !== PALWORLD_KINDS[kind].nxeonServers)
        add({ severity: "error", code: "manifest", path: "Cyrus.json", message: "worksOnNxeonServers must match the mod kind (only server settings presets run on Nxeon's Linux servers)." });
    } catch {
      add({ severity: "error", code: "manifest", path: "Cyrus.json", message: "Cyrus.json is not valid JSON." });
    }
  }

  const luaFiles = files.filter((f) => f.path.endsWith(".lua") && !f.path.startsWith("spec/"));

  if (kind === "server-settings") {
    if (luaFiles.length) add({ severity: "error", code: "structure", message: "A settings preset must not contain scripts." });
    const patch = byPath.get("PalWorldSettings.patch.ini");
    if (!patch) add({ severity: "error", code: "structure", message: "PalWorldSettings.patch.ini is missing." });
    else {
      const entries = [...parseOptionSettings(patch.content)];
      if (!entries.length) add({ severity: "error", code: "settings", path: patch.path, message: "No OptionSettings keys found in the preset." });
      for (const issue of validateSettingsChanges(entries.map(([key, raw]) => ({ key, value: typedValue(key, raw) }))))
        add({ severity: issue.severity, code: "settings", path: patch.path, message: issue.message });
    }
    return { ok: errors.length === 0, kind, errors, warnings };
  }

  // Official loader package
  const infoFile = byPath.get("Info.json");
  let rules: { Type?: unknown; IsServer?: unknown; Targets?: unknown }[] = [];
  if (!infoFile) add({ severity: "error", code: "info", message: "Info.json is missing; Palworld's mod loader only recognises a folder with Info.json at its top." });
  else {
    try {
      const info = JSON.parse(infoFile.content);
      if (typeof info.ModName !== "string" || !info.ModName.trim()) add({ severity: "error", code: "info", path: "Info.json", message: "ModName is required." });
      if (typeof info.PackageName !== "string" || !/^[A-Za-z0-9]{1,64}$/.test(info.PackageName)) add({ severity: "error", code: "info", path: "Info.json", message: "PackageName must be 1-64 letters and digits." });
      if (info.PackageName === "PalSchema" || info.PackageName === PALWORLD_UE4SS_PACKAGE) add({ severity: "error", code: "info", path: "Info.json", message: "PackageName is reserved by a framework package." });
      if (typeof info.Version !== "string" || !info.Version.trim()) add({ severity: "error", code: "version", path: "Info.json", message: "Version must be a non-empty string (the loader reinstalls when it changes)." });
      if (!Number.isInteger(info.MinRevision) || info.MinRevision <= 0) add({ severity: "error", code: "version", path: "Info.json", message: "MinRevision must be a positive whole number (the game revision)." });
      if (typeof info.Author !== "string" || !info.Author.trim()) add({ severity: "warn", code: "info", path: "Info.json", message: "Author is empty." });
      if (info.DebugMode === true) add({ severity: "warn", code: "info", path: "Info.json", message: "DebugMode reinstalls the mod on every launch; ship with false." });
      if (!Array.isArray(info.Dependencies)) add({ severity: "error", code: "info", path: "Info.json", message: "Dependencies must be a list of package names." });
      if (!Array.isArray(info.InstallRule) || !info.InstallRule.length) add({ severity: "error", code: "info", path: "Info.json", message: "InstallRule must list at least one rule." });
      else rules = info.InstallRule;
      for (const r of rules) {
        if (typeof r.Type !== "string" || !INSTALL_TYPES.has(r.Type)) add({ severity: "error", code: "info", path: "Info.json", message: `InstallRule Type must be one of ${[...INSTALL_TYPES].join(", ")}.` });
        if (r.IsServer !== undefined && typeof r.IsServer !== "boolean") add({ severity: "error", code: "info", path: "Info.json", message: "IsServer must be true or false." });
        const targets = Array.isArray(r.Targets) ? r.Targets : [];
        if (!targets.length) add({ severity: "error", code: "info", path: "Info.json", message: "Each InstallRule needs Targets." });
        for (const t of targets) {
          const dir = typeof t === "string" ? t.replace(/^\.\//, "").replace(/\/$/, "") : "";
          if (!dir || dir.includes("..") || dir.startsWith("/")) add({ severity: "error", code: "path", path: "Info.json", message: `Target ${String(t)} must be a folder inside the package.` });
          else if (!files.some((f) => f.path.startsWith(`${dir}/`))) add({ severity: "error", code: "structure", path: "Info.json", message: `Target ./${dir} has no files.` });
        }
      }
      const hasLua = rules.some((r) => r.Type === "Lua");
      if (hasLua && Array.isArray(info.Dependencies) && !info.Dependencies.includes(PALWORLD_UE4SS_PACKAGE))
        add({ severity: "error", code: "info", path: "Info.json", message: "Lua mods must depend on the UE4SS package." });
      const serverRule = rules.some((r) => r.IsServer === true);
      if (kind && (kind === "client-lua" || kind === "host-lua") && serverRule)
        add({ severity: "error", code: "side", path: "Info.json", message: "This mod can't run on a dedicated server, so it must not have an IsServer install rule." });
      if (kind && (kind === "server-lua" || kind === "both-lua") && !serverRule)
        add({ severity: "error", code: "side", path: "Info.json", message: "A server mod needs an InstallRule with IsServer: true, or dedicated servers skip it." });
    } catch {
      add({ severity: "error", code: "info", path: "Info.json", message: "Info.json is not valid JSON." });
    }
  }

  if (rules.some((r) => r.Type === "Lua") && !byPath.has("Scripts/main.lua")) add({ severity: "error", code: "structure", message: "Scripts/main.lua is missing; UE4SS starts Lua mods from it." });
  for (const f of luaFiles) if (!f.path.startsWith("Scripts/")) add({ severity: "error", code: "structure", path: f.path, message: "Lua files must live under Scripts/." });

  const failureRules = support.knowledge?.failureRules ?? [];
  for (const f of luaFiles) {
    const block = luaBlockProblem(f.content);
    if (block) add({ severity: "error", code: "syntax", path: f.path, line: block.line, message: `Lua structure: ${block.message}.` });
    const bracket = luaBracketProblem(f.content);
    if (bracket) add({ severity: "error", code: "syntax", path: f.path, line: bracket.line, message: `Lua structure: ${bracket.message}.` });

    const codeOnly = stripLua(f.content, true); // comments gone, strings kept
    for (const api of support.dangerousApis) {
      const re = new RegExp(api.pattern, "g");
      let m: RegExpExecArray | null;
      while ((m = re.exec(codeOnly))) {
        if (/^\\bio\\.\(open/.test(api.pattern)) break; // handled below with the MOD_DIR rule
        add({ severity: api.severity === "block" ? "error" : "warn", code: "api", path: f.path, line: lineOf(codeOnly, m.index), message: `${m[0].trim()}: ${api.why}` });
        break;
      }
    }
    // File access must be built from MOD_DIR (the mod's own folder).
    const fileRe = /\b(io\.open|io\.lines|loadfile)\s*\(\s*([^,)]*)/g;
    let fm: RegExpExecArray | null;
    while ((fm = fileRe.exec(codeOnly))) {
      if (!/^MOD_DIR\s*\.\./.test(fm[2].trim()))
        add({ severity: "error", code: "file-access", path: f.path, line: lineOf(codeOnly, fm.index), message: `${fm[1]} must use a path built from MOD_DIR (the mod's own folder).` });
    }
    for (const rule of failureRules) {
      const m = new RegExp(rule.detect).exec(f.content);
      if (m) add({ severity: "error", code: `known:${rule.id}`, path: f.path, line: lineOf(f.content, m.index), message: `${rule.why} Fix: ${rule.fix}` });
    }
    const hookRe = /RegisterHook\s*\(\s*["']([^"']+)["']/g;
    let hm: RegExpExecArray | null;
    while ((hm = hookRe.exec(codeOnly))) {
      if (!VERIFIED_HOOKS.has(hm[1])) add({ severity: "warn", code: "hook", path: f.path, line: lineOf(codeOnly, hm.index), message: `Hook ${hm[1]} is not on Cyrus's verified list; check it against the current game version.` });
    }
    if ((kind === "server-lua") && /\bRegisterKeyBind\s*\(/.test(codeOnly))
      add({ severity: "warn", code: "side", path: f.path, message: "Key binds do nothing on a dedicated server; they only work in single-player or for the host." });
  }

  return { ok: errors.length === 0, kind, errors, warnings };
}

