// Palworld support for Cyrus: GameSupport facts, the v2 generator, settings presets and the static validator.
// Pure (no game, no DB): `tsx --test test/cyrus-game-palworld.test.ts`.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import support, { PALWORLD_CURRENT_VERSION, PALWORLD_KINDS } from "../lib/cyrus/games/palworld";
import { mergeOptionSettings, parseOptionSettings, renderPresetFragment, settingsIntent, splitOptionSettings, validateSettingsChanges, PALWORLD_SETTINGS } from "../lib/cyrus/games/palworld.settings";
import { luaBlockProblem, luaBracketProblem, stripLua, validatePalworldMod } from "../lib/cyrus/games/palworld.validate";
import { palworldPackageName, palworldUE4SS } from "../lib/cyrus/engine/games/palworld";
import { buildModFiles } from "../lib/cyrus/engine/templates";
import { CATEGORIES, CATEGORY_BY_KEY, GAME_BY_ID } from "../lib/cyrus/data";
import { CYRUS_GAMES } from "../lib/cyrus/games";
import type { CategoryKey, ModelId, ModFile } from "../lib/cyrus/types";

const game = GAME_BY_ID.palworld;
const input = (category: CategoryKey, prompt: string, model: ModelId = "yakko", version = 1, modName = "Lunar Fox Pack") => ({ game, category: CATEGORY_BY_KEY[category], modName, prompt, model, version });
const MODELS: ModelId[] = ["katara", "saka", "yakko"];
// The 16 universal category ids (lib/cyrus/categories.ts on feature/cyrus-v6-routing).
const UNIVERSAL = ["environment", "creatures", "weapons", "items", "magic", "vehicles", "gameplay", "quests", "minigames", "economy", "admin", "utility", "interface", "visuals", "audio", "performance"];
const PROMPTS = [
  "a frost fox that freezes what it bites",
  "shadow blink strikes that heal me",
  "lightning storm spell",
  "auto harvest helper for my base",
  "neon hud for my pals",
  "summon an army of echoes",
  "pal expedition board that sends idle pals on loot runs",
];
const all = (files: ModFile[]) => files.map((f) => f.content).join("\n");

describe("palworld GameSupport", () => {
  it("is registered, honest about status and well-formed", () => {
    assert.equal(support.id, "palworld");
    assert.ok(CYRUS_GAMES.some((g) => g.id === "palworld"));
    assert.notEqual(CYRUS_GAMES.find((g) => g.id === "palworld")!.status, "live", "going live is the owner's call");
    assert.equal(support.versions.filter((v) => v.status === "current").length, 1);
    assert.equal(support.versions.find((v) => v.status === "current")!.version, PALWORLD_CURRENT_VERSION);
    assert.equal(support.verification.canRunSandbox, false);
    assert.equal(support.verification.method, "static-lint");
    assert.ok(support.sources.length >= 10 && support.unknowns.length >= 3);
    for (const c of support.categories) assert.ok(UNIVERSAL.includes(c), c);
    assert.ok(!support.categories.includes("audio"), "audio needs cooked soundbanks Cyrus can't make");
  });

  it("says plainly that only settings presets run on Nxeon's Linux servers", () => {
    assert.equal(PALWORLD_KINDS["server-settings"].nxeonServers, true);
    for (const k of ["server-lua", "both-lua", "host-lua", "client-lua"] as const) assert.equal(PALWORLD_KINDS[k].nxeonServers, false, k);
    assert.match(PALWORLD_KINDS["server-lua"].reason, /Windows/);
    assert.match(support.install.clientNote ?? "", /Console, Mac and Game Pass/);
  });

  it("every dangerous-API and failure-rule pattern is a valid regex", () => {
    for (const d of support.dangerousApis) assert.doesNotThrow(() => new RegExp(d.pattern), d.pattern);
    assert.ok(support.knowledge && support.knowledge.apiSheet.length > 10);
    for (const r of support.knowledge!.failureRules) assert.doesNotThrow(() => new RegExp(r.detect), r.id);
  });
});

describe("palworld generator v2", () => {
  it("every category, model and prompt builds a package the validator accepts", () => {
    let builds = 0;
    for (const cat of CATEGORIES) {
      for (const model of MODELS) {
        for (const prompt of PROMPTS) {
          const files = buildModFiles(input(cat.key, prompt, model, model === "katara" ? 1 : 2));
          const v = validatePalworldMod(files);
          assert.deepEqual(v.errors, [], `${cat.key}/${model}/${prompt}: ${JSON.stringify(v.errors)}`);
          assert.ok(!/plausible:/.test(all(files)), "no unverified API markers");
          builds++;
        }
      }
    }
    assert.ok(builds >= CATEGORIES.length * 3 * PROMPTS.length);
  });

  it("Katara still ships a loadable mod (main, module, effects, Info.json, Cyrus.json)", () => {
    const files = buildModFiles(input("creatures", "a rare glowing lamball", "katara"));
    const paths = files.map((f) => f.path);
    assert.equal(paths[0], "Scripts/main.lua");
    for (const p of ["Scripts/lunar_fox_pack/effects.lua", "Info.json", "Cyrus.json"]) assert.ok(paths.includes(p), p);
    assert.equal(validatePalworldMod(files).ok, true);
  });

  it("main.lua starts on dedicated servers and players' PCs alike", () => {
    const main = palworldUE4SS(input("worlds", "night spawns")).files.find((f) => f.path === "Scripts/main.lua")!.content;
    assert.match(main, /RegisterInitGameStatePostHook/);
    assert.match(main, /PlayerController:ClientRestart/);
    assert.match(main, /registerHooks\(\)/);
  });

  it("tags each archetype with the side it really runs on, and Info.json follows", () => {
    const kindOf = (cat: CategoryKey, prompt = "a mod") => {
      const files = palworldUE4SS(input(cat, prompt)).files;
      const meta = JSON.parse(files.find((f) => f.path === "Cyrus.json")!.content);
      const info = JSON.parse(files.find((f) => f.path === "Info.json")!.content);
      return { kind: meta.kind, server: info.InstallRule.some((r: { IsServer?: boolean }) => r.IsServer === true), meta };
    };
    assert.deepEqual([kindOf("worlds").kind, kindOf("worlds").server], ["server-lua", true]);
    assert.deepEqual([kindOf("creatures").kind, kindOf("creatures").server], ["server-lua", true]);
    assert.deepEqual([kindOf("vehicles").kind, kindOf("vehicles").server], ["both-lua", true]);
    assert.deepEqual([kindOf("interface").kind, kindOf("interface").server], ["client-lua", false]);
    assert.deepEqual([kindOf("magic").kind, kindOf("magic").server], ["host-lua", false]);
    assert.equal(kindOf("audio").meta.templatePreview !== null, true, "audio is a template preview");
    assert.equal(kindOf("worlds").meta.worksOnNxeonServers, false);
    assert.equal(kindOf("worlds").meta.game.version, PALWORLD_CURRENT_VERSION);
  });

  it("uses only verified names (the old plausible ones are gone)", () => {
    const text = CATEGORIES.map((c) => all(palworldUE4SS(input(c.key, "frost fire storm heal blink summon lunar auto neon")).files)).join("\n");
    for (const gone of ["ApplyDamageForMP", "AddAdditionalEffect", "GetCurrentDayTimeHour", "GetRidingCharacter", "EnterChat_Receive", "SpawnGroupList", "PostEventByName", "BeginDeferredActorSpawnFromClass", "param:SetHP"])
      assert.ok(!text.includes(gone), gone);
    assert.match(text, /CallOnActualDamageProcessed_ToAll/);
    assert.match(text, /AddItem_ServerInternal\(FName\(itemId\), count, false, 0\.0, true\)/);
  });

  it("PackageName is letters and digits and stable across versions", () => {
    const a = palworldPackageName("Lunar Fox Pack");
    assert.match(a, /^[A-Za-z0-9]{1,64}$/);
    assert.equal(a, palworldPackageName("Lunar Fox Pack"));
    const v1 = JSON.parse(palworldUE4SS(input("creatures", "x", "yakko", 1)).files.find((f) => f.path === "Info.json")!.content);
    const v3 = JSON.parse(palworldUE4SS(input("creatures", "x", "yakko", 3)).files.find((f) => f.path === "Info.json")!.content);
    assert.equal(v1.PackageName, v3.PackageName);
    assert.notEqual(v1.Version, v3.Version);
    assert.deepEqual(v1.Dependencies, ["UE4SS"]);
  });

  it("README install steps match the mod kind", () => {
    const client = buildModFiles(input("interface", "pal stats overlay", "saka")).find((f) => f.path === "README.md")!.content;
    assert.match(client, /Mod Management/);
    assert.doesNotMatch(client, /PalServer\.exe/);
    const server = buildModFiles(input("worlds", "tougher nights", "saka")).find((f) => f.path === "README.md")!.content;
    assert.match(server, /Windows dedicated server only/);
  });
});

describe("palworld server settings presets", () => {
  it("turns a plain settings request into a preset, not a script", () => {
    const files = buildModFiles(input("mechanics", "double xp and 3x capture rate with shorter nights on my server", "saka", 1, "Fast Leveling"));
    const paths = files.map((f) => f.path);
    assert.ok(paths.includes("PalWorldSettings.patch.ini") && paths.includes("Cyrus.json"));
    assert.ok(!paths.some((p) => p.endsWith(".lua")));
    const meta = JSON.parse(files.find((f) => f.path === "Cyrus.json")!.content);
    assert.equal(meta.kind, "server-settings");
    assert.equal(meta.worksOnNxeonServers, true);
    const v = validatePalworldMod(files);
    assert.deepEqual(v.errors, []);
    const keys = Object.fromEntries(meta.settings.map((s: { key: string; value: unknown }) => [s.key, s.value]));
    assert.equal(keys.ExpRate, 2);
    assert.equal(keys.PalCaptureRate, 3);
    assert.equal(keys.NightTimeSpeedRate, 2);
  });

  it("Katara keeps the preset files", () => {
    const files = buildModFiles(input("mechanics", "hardcore server rules with no fast travel", "katara", 1, "Hard Mode"));
    assert.deepEqual(files.map((f) => f.path).slice(0, 2), ["Cyrus.json", "PalWorldSettings.patch.ini"]);
    assert.equal(validatePalworldMod(files).ok, true);
  });

  it("leaves creative prompts alone", () => {
    assert.deepEqual(settingsIntent("a frost fox that freezes what it bites"), []);
    assert.deepEqual(settingsIntent("pal expedition board for idle pals"), []);
  });

  it("clamps silly numbers and flags destructive and heavy settings", () => {
    const c = settingsIntent("xp x500 hardcore server with more pals per base");
    const xp = c.find((x) => x.key === "ExpRate")!;
    assert.equal(xp.value, 20);
    const issues = validateSettingsChanges(c);
    assert.ok(issues.some((i) => i.key === "bHardcore" && i.severity === "warn"));
    assert.ok(issues.some((i) => i.key === "BaseCampWorkerMaxNum" && i.severity === "warn"));
    assert.ok(!issues.some((i) => i.severity === "error"));
  });

  it("rejects panel-owned, unknown and out-of-range keys", () => {
    const issues = validateSettingsChanges([
      { key: "AdminPassword", value: "x" },
      { key: "MadeUpRate", value: 2 },
      { key: "BaseCampWorkerMaxNum", value: 80 },
      { key: "DeathPenalty", value: "Everything" },
      { key: "bIsPvP", value: 1 },
    ]);
    assert.equal(issues.filter((i) => i.severity === "error").length, 5);
  });

  it("merges into an existing line without touching other keys", () => {
    const ini = `[/Script/Pal.PalGameWorldSettings]\nOptionSettings=(Difficulty=None,ExpRate=1.000000,ServerName="My (cool) server, eh",CrossplayPlatforms=(Steam,Xbox,PS5,Mac),bIsPvP=False)\n`;
    const out = mergeOptionSettings(ini, [{ key: "ExpRate", value: 2.5 }, { key: "bEnableInvaderEnemy", value: false }]);
    const m = parseOptionSettings(out);
    assert.equal(m.get("ExpRate"), "2.500000");
    assert.equal(m.get("bEnableInvaderEnemy"), "False");
    assert.equal(m.get("ServerName"), '"My (cool) server, eh"');
    assert.equal(m.get("CrossplayPlatforms"), "(Steam,Xbox,PS5,Mac)");
    assert.equal(m.get("bIsPvP"), "False");
    assert.equal(out.split("\n").filter((l) => l.startsWith("OptionSettings=")).length, 1);
    assert.match(mergeOptionSettings("", [{ key: "ExpRate", value: 2 }]), /^\[\/Script\/Pal\.PalGameWorldSettings\]\nOptionSettings=\(ExpRate=2\.000000\)/);
  });

  it("every spec key renders and parses back", () => {
    const changes = PALWORLD_SETTINGS.map((s) => ({ key: s.key, value: s.default }));
    const parsed = splitOptionSettings(renderPresetFragment(changes).split("OptionSettings=(")[1].replace(/\)\n$/, ""));
    assert.equal(parsed.length, PALWORLD_SETTINGS.length);
    assert.deepEqual(validateSettingsChanges(changes).filter((i) => i.severity === "error"), []);
  });
});

describe("palworld validator", () => {
  const good = () => palworldUE4SS(input("worlds", "night spawns")).files.map((f) => ({ ...f }));
  const withLua = (extra: string) => good().map((f) => (f.path.endsWith("/spawns.lua") ? { ...f, content: f.content.replace("return M", `${extra}\nreturn M`) } : f));
  const codes = (files: { path: string; content: string }[]) => validatePalworldMod(files).errors.map((e) => e.code);

  it("blocks shell, native code, save files and stray file access", () => {
    assert.ok(codes(withLua('os.execute("rm -rf /")')).includes("api"));
    assert.ok(codes(withLua('local f = package.loadlib("x.dll", "init")')).includes("api"));
    assert.ok(codes(withLua('local s = "Pal/Saved/SaveGames/0/Level.sav"')).includes("api"));
    assert.ok(codes(withLua('local h = io.open("/etc/passwd")')).includes("file-access"));
    assert.ok(codes(withLua('local r = require("socket")')).includes("api"));
  });

  it("ignores dangerous words inside comments", () => {
    assert.deepEqual(codes(withLua("-- never call os.execute() here")), []);
  });

  it("catches broken Lua structure", () => {
    assert.ok(codes(withLua("function M.broken()\n  if true then\nend")).includes("syntax"));
    assert.equal(luaBlockProblem("for i = 1, 3 do\n  while x do x = f() end\nend\nrepeat y() until z"), null);
    assert.equal(luaBlockProblem('local s = "end end" -- function\nlocal t = [[ if ]]'), null);
    assert.ok(luaBlockProblem("local function a()\n"));
    assert.ok(luaBracketProblem("f(1, {2)"));
    assert.equal(stripLua('a = "x" -- c').includes("c"), false);
  });

  it("enforces the official package format and the side rules", () => {
    const noInfo = good().filter((f) => f.path !== "Info.json");
    assert.ok(codes(noInfo).includes("info"));
    const badName = good().map((f) => (f.path === "Info.json" ? { ...f, content: f.content.replace(/"PackageName": "[^"]+"/, '"PackageName": "Bad Name!"') } : f));
    assert.ok(codes(badName).includes("info"));
    const overlay = palworldUE4SS(input("interface", "stats")).files.map((f) =>
      f.path === "Info.json" ? { ...f, content: f.content.replace('"InstallRule": [', '"InstallRule": [\n    { "Type": "Lua", "IsServer": true, "Targets": ["./Scripts"] },') } : f,
    );
    assert.ok(codes(overlay).includes("side"));
    const noMain = good().filter((f) => f.path !== "Scripts/main.lua");
    assert.ok(codes(noMain).includes("structure"));
  });

  it("applies the knowledge pack's known failure patterns", () => {
    assert.ok(codes(withLua("local function x(param) param:SetHP({ Value = 1 }) end")).includes("known:sethp-on-parameter"));
    assert.ok(codes(withLua('RegisterHook("/Script/Pal.PalDamageReactionComponent:ApplyDamageForMP", function() end)')).includes("known:missing-damage-function"));
    assert.ok(codes(withLua("-- plausible: made up")).includes("known:unverified-name"));
  });

  it("flags outdated builds and settings presets with blocked keys", () => {
    const old = good().map((f) => (f.path === "Cyrus.json" ? { ...f, content: f.content.replace(`"version": "${PALWORLD_CURRENT_VERSION}"`, '"version": "0.7.3"') } : f));
    assert.ok(validatePalworldMod(old).warnings.some((w) => w.code === "outdated"));
    const preset = buildModFiles(input("mechanics", "double xp server", "saka", 1, "Xp")).map((f) =>
      f.path === "PalWorldSettings.patch.ini" ? { ...f, content: f.content.replace("OptionSettings=(", 'OptionSettings=(AdminPassword="hunter2",') } : f,
    );
    assert.ok(codes(preset).includes("settings"));
  });
});

