  const meta = (files: ModFile[]) => JSON.parse(files.find((f) => f.path === "Cyrus.json")!.content);
  it("only client-side tips are built as scripts", () => {
    assert.deepEqual([...NXEON_PALWORLD_LUA], ["client-lua"]);
    const overlay = buildModFiles(input("interface", "pal stats overlay", "saka"));
    assert.equal(meta(overlay).kind, "client-lua");
    assert.match(meta(overlay).warnings.join(" "), /Client-side only/);
  });

  it("refuses server scripts and offers the closest settings preset", () => {
    const spawns = buildModFiles(input("worlds", "night spawns", "saka"));
    const m = meta(spawns);
    assert.equal(m.kind, "server-settings");
    assert.equal(m.refused.requested, "server-lua");
    assert.match(m.refused.reason, /Linux/);
    assert.ok(m.settings.some((s: { key: string }) => s.key === "PalSpawnNumRate"));
    assert.ok(!spawns.some((f) => f.path.endsWith(".lua") || f.path === "Info.json"));
    const work = meta(buildModFiles(input("mechanics", "base workers work harder", "saka")));
    assert.ok(work.settings.some((s: { key: string; value: number }) => s.key === "WorkSpeedRate" && s.value === 2));
  });

  it("refuses host-only and both-sides scripts with no fake alternative when none exists", () => {
    for (const cat of ["creatures", "magic", "vehicles", "quests"] as CategoryKey[]) {
      const files = buildModFiles(input(cat, "a mod", "saka"));
      const m = meta(files);
      assert.equal(m.kind, "unsupported", cat);
      assert.ok(m.refused.reason.length > 20);
      assert.ok(files.some((f) => f.path === "NOTES.md"));
      assert.equal(validatePalworldMod(files).ok, true);
    }
  });

  it("the Nxeon validator rejects a server script package", () => {
    const { built } = palworldLuaPackage(input("worlds", "night spawns"));
    assert.ok(validatePalworldMod(built.files).errors.some((e) => e.code === "nxeon-linux"));
  });
});

describe("palworld server settings presets", () => {''')
