// Temporary: dumps sample Palworld outputs as JSON to stdout (deleted after use, never committed).
import { buildModFiles } from "./lib/cyrus/engine/templates";
import { CATEGORY_BY_KEY, GAME_BY_ID } from "./lib/cyrus/data";
import { validatePalworldMod } from "./lib/cyrus/games/palworld.validate";
import type { CategoryKey } from "./lib/cyrus/types";
const game = GAME_BY_ID.palworld;
const cases: [CategoryKey, string, string][] = [
  ["mechanics", "Double XP and capture rate on my Palworld server, with shorter nights", "Fast Weekend"],
  ["worlds", "tougher night spawns with more drops", "Night Hunt"],
  ["creatures", "rare glowing foxparks variants at night", "Lumina Fox"],
  ["interface", "a pal stats overlay that shows IVs when I look at a pal", "Pal Lens"],
];
const out = cases.map(([cat, prompt, modName]) => {
  const files = buildModFiles({ game, category: CATEGORY_BY_KEY[cat], modName, prompt, model: "yakko", version: 1 });
  return { cat, prompt, validation: validatePalworldMod(files), files };
});
console.log(JSON.stringify(out, null, 2));

